SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE DATABASE IF NOT EXISTS `db_agents_orchestrator` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_agents_orchestrator`;

DROP TABLE IF EXISTS `tbl_accreditation_indicators`;
CREATE TABLE `tbl_accreditation_indicators` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `indicator_code` varchar(32) NOT NULL,
  `study_program_id` int(11) DEFAULT NULL,
  `standard_name` varchar(160) NOT NULL,
  `target_value` decimal(6,2) NOT NULL,
  `actual_value` decimal(6,2) NOT NULL,
  `compliance_status` enum('met','watch','critical') NOT NULL DEFAULT 'met',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ai_code_prog` (`indicator_code`,`study_program_id`),
  KEY `fk_ai_prog` (`study_program_id`),
  CONSTRAINT `fk_ai_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_accreditation_indicators` (`id`, `indicator_code`, `study_program_id`, `standard_name`, `target_value`, `actual_value`, `compliance_status`, `updated_at`) VALUES
