DROP TABLE IF EXISTS `tbl_agent_collaborations`;
CREATE TABLE `tbl_agent_collaborations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL,
  `parent_agent_id` int(11) DEFAULT NULL,
  `child_agent_id` int(11) NOT NULL,
  `subtask_prompt` text NOT NULL,
  `result_summary` text DEFAULT NULL,
  `status` enum('pending','running','completed','failed') NOT NULL DEFAULT 'pending',
  `sequence_order` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ac_task_seq` (`task_id`,`sequence_order`),
  KEY `fk_ac_child` (`child_agent_id`),
  CONSTRAINT `fk_ac_child` FOREIGN KEY (`child_agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ac_task` FOREIGN KEY (`task_id`) REFERENCES `tbl_agent_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_agent_configurations`;
CREATE TABLE `tbl_agent_configurations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) NOT NULL,
  `provider` varchar(32) NOT NULL DEFAULT 'openai',
  `model_name` varchar(64) NOT NULL DEFAULT 'gpt-4.1-mini',
  `temperature` decimal(3,2) DEFAULT 0.40,
  `max_output_tokens` int(11) NOT NULL DEFAULT 900,
  `reasoning_effort` varchar(16) DEFAULT 'low',
  `response_format_json` text DEFAULT NULL,
  `timeout_seconds` int(11) NOT NULL DEFAULT 25,
  `max_retries` int(11) NOT NULL DEFAULT 1,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_cfg_agent` (`agent_id`),
  CONSTRAINT `fk_acfg_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

