DROP TABLE IF EXISTS `tbl_agent_events`;
CREATE TABLE `tbl_agent_events` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `agent_code` varchar(64) NOT NULL,
  `status` varchar(32) NOT NULL,
  `task_label` varchar(255) NOT NULL,
  `progress` int(11) NOT NULL DEFAULT 0,
  `animation` varchar(32) NOT NULL DEFAULT 'idle',
  `zone_code` varchar(32) NOT NULL DEFAULT 'COMMAND_CENTER',
  `payload_json` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ae_user_id` (`user_id`,`id`),
  KEY `idx_ae_task_id` (`task_id`,`id`),
  CONSTRAINT `fk_ae_task` FOREIGN KEY (`task_id`) REFERENCES `tbl_agent_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_agent_execution_history`;
CREATE TABLE `tbl_agent_execution_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL,
  `agent_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `model_used` varchar(64) NOT NULL,
  `prompt_tokens` int(11) NOT NULL DEFAULT 0,
  `completion_tokens` int(11) NOT NULL DEFAULT 0,
  `total_tokens` int(11) NOT NULL DEFAULT 0,
  `estimated_cost_usd` decimal(10,6) NOT NULL DEFAULT 0.000000,
  `latency_ms` int(11) NOT NULL DEFAULT 0,
  `status` enum('completed','failed','fallback') NOT NULL DEFAULT 'completed',
  `output_excerpt` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_aeh_agent_created` (`agent_id`,`created_at`),
  KEY `idx_aeh_task` (`task_id`),
  CONSTRAINT `fk_aeh_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_aeh_task` FOREIGN KEY (`task_id`) REFERENCES `tbl_agent_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_agent_knowledge`;
CREATE TABLE `tbl_agent_knowledge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) NOT NULL,
  `knowledge_base_id` int(11) NOT NULL,
  `priority_order` int(11) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ak` (`agent_id`,`knowledge_base_id`),
  KEY `fk_ak_kb` (`knowledge_base_id`),
  CONSTRAINT `fk_ak_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ak_kb` FOREIGN KEY (`knowledge_base_id`) REFERENCES `tbl_knowledge_bases` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

