DROP TABLE IF EXISTS `tbl_agent_task_logs`;
CREATE TABLE `tbl_agent_task_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) NOT NULL,
  `agent_id` int(11) DEFAULT NULL,
  `step_type` varchar(48) NOT NULL,
  `tool_code` varchar(64) DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'ok',
  `summary` text NOT NULL,
  `duration_ms` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_atl_task_created` (`task_id`,`created_at`),
  KEY `fk_atl_agent` (`agent_id`),
  CONSTRAINT `fk_atl_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_atl_task` FOREIGN KEY (`task_id`) REFERENCES `tbl_agent_tasks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_agent_tasks`;
CREATE TABLE `tbl_agent_tasks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_uuid` varchar(64) NOT NULL,
  `user_id` int(11) NOT NULL,
  `role_code` varchar(32) NOT NULL,
  `study_program_id` int(11) DEFAULT NULL,
  `conversation_id` int(11) DEFAULT NULL,
  `user_message` text NOT NULL,
  `execution_mode` enum('single','multi') NOT NULL DEFAULT 'single',
  `status` enum('queued','routing','running','completed','failed') NOT NULL DEFAULT 'queued',
  `progress` int(11) NOT NULL DEFAULT 0,
  `total_agents` int(11) NOT NULL DEFAULT 1,
  `latency_ms` int(11) NOT NULL DEFAULT 0,
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_uuid` (`task_uuid`),
  KEY `idx_tasks_user_status` (`user_id`,`status`,`created_at`),
  KEY `fk_task_conv` (`conversation_id`),
  CONSTRAINT `fk_task_conv` FOREIGN KEY (`conversation_id`) REFERENCES `tbl_conversations` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_task_user` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_agent_tool_permissions`;
CREATE TABLE `tbl_agent_tool_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) NOT NULL,
  `tool_id` int(11) NOT NULL,
  `granted_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_atp` (`agent_id`,`tool_id`),
  KEY `fk_atp_tool` (`tool_id`),
  CONSTRAINT `fk_atp_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_atp_tool` FOREIGN KEY (`tool_id`) REFERENCES `tbl_agent_tools` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

