DROP TABLE IF EXISTS `tbl_agent_tools`;
CREATE TABLE `tbl_agent_tools` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tool_code` varchar(64) NOT NULL,
  `tool_name` varchar(120) NOT NULL,
  `tool_category` varchar(48) NOT NULL DEFAULT 'FILKOM_Domain',
  `trigger_keywords` text NOT NULL,
  `description` text NOT NULL,
  `parameters_schema_json` text DEFAULT NULL,
  `handler_method` varchar(100) NOT NULL,
  `required_permission` varchar(64) DEFAULT 'agents.use',
  `scope_type` enum('GLOBAL','PROGRAM_SCOPED','STUDENT_SCOPED','UPMF_SCOPED','RESEARCH_SCOPED','ADMIN_SCOPED') NOT NULL DEFAULT 'GLOBAL',
  `is_destructive` tinyint(1) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `call_count` int(11) NOT NULL DEFAULT 0,
  `last_called_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tool_code` (`tool_code`),
  KEY `idx_tool_cat_active` (`tool_category`,`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

