DROP TABLE IF EXISTS `tbl_agent_versions`;
CREATE TABLE `tbl_agent_versions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_id` int(11) NOT NULL,
  `version_number` int(11) NOT NULL DEFAULT 1,
  `config_snapshot_json` longtext NOT NULL,
  `change_note` varchar(255) DEFAULT 'Initial version',
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_ver` (`agent_id`,`version_number`),
  CONSTRAINT `fk_av_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

