DROP TABLE IF EXISTS `tbl_agents`;
CREATE TABLE `tbl_agents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_code` varchar(64) NOT NULL,
  `agent_name` varchar(120) NOT NULL,
  `description` text NOT NULL,
  `agent_category` varchar(64) NOT NULL,
  `zone_code` varchar(32) NOT NULL DEFAULT 'COMMAND_CENTER',
  `avatar_model` varchar(120) NOT NULL DEFAULT 'Asian_F_1_Medi_fast.glb',
  `avatar_outfit` varchar(64) NOT NULL DEFAULT 'classic_navy',
  `animation_profile` varchar(64) NOT NULL DEFAULT 'executive_briefing',
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `approval_status` enum('approved','pending_approval','rejected') NOT NULL DEFAULT 'approved',
  `is_ai_generated` tinyint(1) NOT NULL DEFAULT 0,
  `priority` int(11) NOT NULL DEFAULT 50,
  `current_version_id` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `approved_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_code` (`agent_code`),
  KEY `idx_agent_status_prio` (`status`,`approval_status`,`priority`),
  KEY `idx_agent_zone` (`zone_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

