  `id` int(11) NOT NULL AUTO_INCREMENT,
  `provider` varchar(32) NOT NULL DEFAULT 'openai',
  `key_label` varchar(100) NOT NULL,
  `api_key_encrypted` text NOT NULL,
  `api_key_masked` varchar(64) NOT NULL,
  `model_name` varchar(64) NOT NULL DEFAULT 'gpt-4.1-mini',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_primary` tinyint(1) NOT NULL DEFAULT 1,
  `total_requests` int(11) NOT NULL DEFAULT 0,
  `total_tokens` int(11) NOT NULL DEFAULT 0,
  `last_status` varchar(64) DEFAULT 'Standby (Ready)',
  `last_used_at` datetime DEFAULT NULL,
  `created_by` varchar(64) DEFAULT 'admin',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_api_usage_logs`;
CREATE TABLE `tbl_api_usage_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_id` int(11) DEFAULT NULL,
  `agent_id` int(11) DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `provider` varchar(32) NOT NULL DEFAULT 'openai',
  `model_name` varchar(64) NOT NULL,
  `endpoint` varchar(64) NOT NULL DEFAULT '/v1/responses',
  `prompt_tokens` int(11) NOT NULL DEFAULT 0,
  `completion_tokens` int(11) NOT NULL DEFAULT 0,
  `total_tokens` int(11) NOT NULL DEFAULT 0,
  `estimated_cost_usd` decimal(10,6) NOT NULL DEFAULT 0.000000,
  `http_status` int(11) NOT NULL DEFAULT 200,
  `latency_ms` int(11) NOT NULL DEFAULT 0,
  `status` enum('success','error','fallback') NOT NULL DEFAULT 'success',
  `error_message` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_aul_created` (`created_at`),
  KEY `idx_aul_agent` (`agent_id`,`created_at`),
  KEY `idx_aul_provider` (`provider`,`model_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_attendance_records`;
