  `attendance_pct` decimal(5,2) NOT NULL DEFAULT 87.50,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_att_enroll` (`enrollment_id`),
  CONSTRAINT `fk_att_enroll` FOREIGN KEY (`enrollment_id`) REFERENCES `tbl_student_enrollments` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

