DROP TABLE IF EXISTS `tbl_audit_logs`;
CREATE TABLE `tbl_audit_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `action` varchar(80) NOT NULL,
  `target_table` varchar(64) NOT NULL,
  `record_id` varchar(64) DEFAULT NULL,
  `description` text NOT NULL,
  `user_id` varchar(64) DEFAULT NULL,
  `user_name` varchar(120) DEFAULT NULL,
  `role_code` varchar(50) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_audit_created` (`created_at`),
  KEY `idx_audit_target` (`target_table`,`action`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_conversation_flows`;
CREATE TABLE `tbl_conversation_flows` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `flow_key` varchar(128) NOT NULL,
  `from_intent` varchar(64) NOT NULL,
  `to_intent` varchar(64) NOT NULL,
  `last_response_source` varchar(64) NOT NULL DEFAULT 'Static KB',
  `total_transitions` int(11) NOT NULL DEFAULT 1,
  `stall_count` int(11) NOT NULL DEFAULT 0,
  `rephrase_loop_count` int(11) NOT NULL DEFAULT 0,
  `abandon_count` int(11) NOT NULL DEFAULT 0,
  `avg_satisfaction` decimal(4,2) NOT NULL DEFAULT 0.00,
  `auto_recovery_prompt_id` varchar(255) DEFAULT NULL,
  `auto_recovery_prompt_en` varchar(255) DEFAULT NULL,
  `last_updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_flow_key` (`flow_key`),
  KEY `idx_stall` (`stall_count`,`rephrase_loop_count`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_conversations`;
CREATE TABLE `tbl_conversations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `conversation_uuid` varchar(64) NOT NULL,
  `user_id` int(11) NOT NULL,
  `role_code` varchar(32) NOT NULL,
  `title` varchar(180) NOT NULL DEFAULT 'Orchestration Session',
  `last_agent_code` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_conv_uuid` (`conversation_uuid`),
  KEY `idx_conv_user_updated` (`user_id`,`updated_at`),
  CONSTRAINT `fk_conv_user` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_correspondence`;
CREATE TABLE `tbl_correspondence` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `ref_number` varchar(64) NOT NULL,
  `direction` enum('incoming','outgoing') NOT NULL DEFAULT 'outgoing',
