DROP TABLE IF EXISTS `tbl_knowledge_chunks`;
CREATE TABLE `tbl_knowledge_chunks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `document_id` int(11) NOT NULL,
  `chunk_index` int(11) NOT NULL DEFAULT 1,
  `section_title` varchar(200) NOT NULL,
  `chunk_text` text NOT NULL,
  `keywords_text` text NOT NULL,
  `vector_json` longtext NOT NULL,
  `embedding_json` longtext DEFAULT NULL,
  `embedding_model` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_kc_doc_idx` (`document_id`,`chunk_index`),
  FULLTEXT KEY `idx_kc_ft` (`section_title`,`chunk_text`),
  CONSTRAINT `fk_kc_doc` FOREIGN KEY (`document_id`) REFERENCES `tbl_knowledge_documents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_knowledge_chunks` (`id`, `document_id`, `chunk_index`, `section_title`, `chunk_text`, `keywords_text`, `vector_json`, `embedding_json`, `embedding_model`, `created_at`) VALUES
(1, 1, 1, 'Pedoman Akademik & Skripsi FILKOM 2026', 'Syarat pengambilan Skripsi di FILKOM : mahasiswa telah menempuh minimal 120 SKS, lulus Metodologi Penelitian, memiliki IPK minimal 2.50, dan mendapat persetujuan Kaprodi.\n\nBatas indeks kemiripan Turnitin untuk proposal dan naskah akhir skripsi maksimal 20%. Mahasiswa wajib memiliki kehadiran perkuliahan minimal 80% untuk mengikuti Ujian Akhir Semester (UAS).', 'skripsi, minimal, filkom, mahasiswa, memiliki, akhir, pedoman, akademik, 2026, syarat, pengambilan, , telah, menempuh', '{\"skripsi\":0.378,\"minimal\":0.378,\"filkom\":0.252,\"mahasiswa\":0.252,\"memiliki\":0.252,\"akhir\":0.252,\"pedoman\":0.126,\"akademik\":0.126,\"2026\":0.126,\"syarat\":0.126,\"pengambilan\":0.126,\"sfsfs\":0.126,\"telah\":0.126,\"menempuh\":0.126,\"120\":0.126,\"sks\":0.126,\"lulus\":0.126,\"metodologi\":0.126,\"penelitian\":0.126,\"ipk\":0.126,\"mendapat\":0.126,\"persetujuan\":0.126,\"kaprodi\":0.126,\"batas\":0.126,\"indeks\":0.126,\"kemiripan\":0.126,\"turnitin\":0.126,\"proposal\":0.126,\"naskah\":0.126,\"maksimal\":0.126,\"wajib\":0.126,\"kehadiran\":0.126,\"perkuliahan\":0.126,\"mengikuti\":0.126,\"ujian\":0.126}', NULL, NULL, '2026-11-24 13:41:08'),
(2, 2, 1, 'Standar Mutu & Akreditasi LAM INFOKOM UPMF', 'Unit Penjaminan Mutu Fakultas (UPMF) melaksanakan Audit Mutu Internal (AMI) setiap semester untuk memastikan standar pembelajaran, kelulusan tepat waktu minimal 85%, dan rasio publikasi dosen.\n\nProgram studi dengan indikator status watch wajib menyusun rencana tindak lanjut dalam 14 hari kerja.', 'mutu, standar, upmf, akreditasi, lam, infokom, unit, penjaminan, fakultas, melaksanakan, audit, internal, ami, setiap', '{\"mutu\":0.4286,\"standar\":0.2857,\"upmf\":0.2857,\"akreditasi\":0.1429,\"lam\":0.1429,\"infokom\":0.1429,\"unit\":0.1429,\"penjaminan\":0.1429,\"fakultas\":0.1429,\"melaksanakan\":0.1429,\"audit\":0.1429,\"internal\":0.1429,\"ami\":0.1429,\"setiap\":0.1429,\"semester\":0.1429,\"memastikan\":0.1429,\"pembelajaran\":0.1429,\"kelulusan\":0.1429,\"tepat\":0.1429,\"waktu\":0.1429,\"minimal\":0.1429,\"rasio\":0.1429,\"publikasi\":0.1429,\"dosen\":0.1429,\"program\":0.1429,\"studi\":0.1429,\"indikator\":0.1429,\"status\":0.1429,\"watch\":0.1429,\"wajib\":0.1429,\"menyusun\":0.1429,\"rencana\":0.1429,\"tindak\":0.1429,\"lanjut\":0.1429,\"hari\":0.1429}', NULL, NULL, '2026-11-24 13:41:08'),
(3, 3, 1, 'Panduan Hibah Riset & Insentif Publikasi FILKOM', 'Pusat Riset FILKOM memfasilitasi hibah internal , hibah DRTPM Kemendikbudristek, dan kolaborasi industri. Dosen dengan publikasi Scopus Q1/Q2 atau SINTA 1/2 memperoleh poin kinerja riset dan dukungan pendanaan konferensi IEEE.', 'hibah, riset, publikasi, filkom, panduan, insentif, pusat, memfasilitasi, internal, , drtpm, kemendikbudristek, kolaborasi, industri', '{\"hibah\":0.4423,\"riset\":0.4423,\"publikasi\":0.2949,\"filkom\":0.2949,\"panduan\":0.1474,\"insentif\":0.1474,\"pusat\":0.1474,\"memfasilitasi\":0.1474,\"internal\":0.1474,\"tertete\":0.1474,\"drtpm\":0.1474,\"kemendikbudristek\":0.1474,\"kolaborasi\":0.1474,\"industri\":0.1474,\"dosen\":0.1474,\"scopus\":0.1474,\"sinta\":0.1474,\"memperoleh\":0.1474,\"poin\":0.1474,\"kinerja\":0.1474,\"dukungan\":0.1474,\"pendanaan\":0.1474,\"konferensi\":0.1474,\"ieee\":0.1474}', NULL, NULL, '2026-11-24 13:41:08'),
(4, 4, 1, 'SOP Tata Kelola Surat & Rapat Fakultas', 'Sekretariat FILKOM mengelola penomoran surat resmi fakultas, agenda rapat senat, notulensi rapat koordinasi program studi, dan pengarsipan SK Dekan secara digital.', 'rapat, surat, fakultas, sop, tata, kelola, sekretariat, filkom, mengelola, penomoran, resmi, agenda, senat, notulensi', '{\"rapat\":0.5071,\"surat\":0.3381,\"fakultas\":0.3381,\"sop\":0.169,\"tata\":0.169,\"kelola\":0.169,\"sekretariat\":0.169,\"filkom\":0.169,\"mengelola\":0.169,\"penomoran\":0.169,\"resmi\":0.169,\"agenda\":0.169,\"senat\":0.169,\"notulensi\":0.169,\"koordinasi\":0.169,\"program\":0.169,\"studi\":0.169,\"pengarsipan\":0.169,\"dekan\":0.169,\"secara\":0.169,\"digital\":0.169}', NULL, NULL, '2026-11-24 13:41:08'),
(5, 5, 1, 'Rencana Strategis FILKOM 2025-2029', 'Renstra FILKOM menargetkan transformasi kampus berbasis AI Orchestration, akreditasi Unggul di seluruh program studi S1 dan S2, peningkatan riset terapan AI & Cybersecurity, serta kesiapan lulusan industri.', 'filkom, rencana, strategis, 2025, 2029, renstra, menargetkan, transformasi, kampus, berbasis, orchestration, akreditasi, unggul, seluruh', '{\"filkom\":0.3849,\"rencana\":0.1925,\"strategis\":0.1925,\"2025\":0.1925,\"2029\":0.1925,\"renstra\":0.1925,\"menargetkan\":0.1925,\"transformasi\":0.1925,\"kampus\":0.1925,\"berbasis\":0.1925,\"orchestration\":0.1925,\"akreditasi\":0.1925,\"unggul\":0.1925,\"seluruh\":0.1925,\"program\":0.1925,\"studi\":0.1925,\"peningkatan\":0.1925,\"riset\":0.1925,\"terapan\":0.1925,\"cybersecurity\":0.1925,\"serta\":0.1925,\"kesiapan\":0.1925,\"lulusan\":0.1925,\"industri\":0.1925}', NULL, NULL, '2026-11-24 13:41:08'),
(6, 6, 1, 'Buku Panduan Layanan Mahasiswa FILKOM', 'Mahasiswa dapat berkonsultasi dengan Dosen Penasehat Akademik (PA) sebelum pengisian KRS maksimal 24 SKS sesuai IPS. Layanan beasiswa mencakup Beasiswa Prestasi, KIP-Kuliah, dan Student Labor.', 'layanan, mahasiswa, beasiswa, buku, panduan, filkom, dapat, berkonsultasi, dosen, penasehat, akademik, sebelum, pengisian, krs', '{\"layanan\":0.3482,\"mahasiswa\":0.3482,\"beasiswa\":0.3482,\"buku\":0.1741,\"panduan\":0.1741,\"filkom\":0.1741,\"dapat\":0.1741,\"berkonsultasi\":0.1741,\"dosen\":0.1741,\"penasehat\":0.1741,\"akademik\":0.1741,\"sebelum\":0.1741,\"pengisian\":0.1741,\"krs\":0.1741,\"maksimal\":0.1741,\"sks\":0.1741,\"sesuai\":0.1741,\"ips\":0.1741,\"mencakup\":0.1741,\"prestasi\":0.1741,\"kip\":0.1741,\"kuliah\":0.1741,\"student\":0.1741,\"labor\":0.1741}', NULL, NULL, '2026-11-24 13:41:08');

DROP TABLE IF EXISTS `tbl_knowledge_documents`;
CREATE TABLE `tbl_knowledge_documents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `doc_code` varchar(64) NOT NULL,
  `knowledge_base_id` int(11) DEFAULT 1,
  `title` varchar(200) NOT NULL,
  `category` varchar(64) NOT NULL DEFAULT 'Academic',
  `file_name` varchar(180) NOT NULL,
  `file_type` enum('PDF','DOCX','XLSX','TXT') NOT NULL DEFAULT 'TXT',
  `file_size_bytes` int(11) NOT NULL DEFAULT 0,
  `content_text` longtext NOT NULL,
  `chunk_count` int(11) NOT NULL DEFAULT 0,
  `retrieval_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `uploaded_by` varchar(64) DEFAULT 'admin',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_doc_code` (`doc_code`),
  KEY `idx_kd_kb_active` (`knowledge_base_id`,`is_active`),
  CONSTRAINT `fk_kd_kb` FOREIGN KEY (`knowledge_base_id`) REFERENCES `tbl_knowledge_bases` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_knowledge_documents` (`id`, `doc_code`, `knowledge_base_id`, `title`, `category`, `file_name`, `file_type`, `file_size_bytes`, `content_text`, `chunk_count`, `retrieval_count`, `is_active`, `uploaded_by`, `created_at`, `updated_at`) VALUES
(1, 'DOC-FILKOM-01', 2, 'Pedoman Akademik & Skripsi FILKOM 2026', 'Academic', 'Pedoman_Akademik_FILKOM_2026.txt', 'TXT', 366, 'Syarat pengambilan Skripsi di FILKOM : mahasiswa telah menempuh minimal 120 SKS, lulus Metodologi Penelitian, memiliki IPK minimal 2.50, dan mendapat persetujuan Kaprodi.\n\nBatas indeks kemiripan Turnitin untuk proposal dan naskah akhir skripsi maksimal 20%. Mahasiswa wajib memiliki kehadiran perkuliahan minimal 80% untuk mengikuti Ujian Akhir Semester (UAS).', 1, 2, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 14:03:28'),
(2, 'DOC-UPMF-01', 4, 'Standar Mutu & Akreditasi LAM INFOKOM UPMF', 'Quality Assurance', 'Standar_Mutu_UPMF_2026.txt', 'TXT', 295, 'Unit Penjaminan Mutu Fakultas (UPMF) melaksanakan Audit Mutu Internal (AMI) setiap semester untuk memastikan standar pembelajaran, kelulusan tepat waktu minimal 85%, dan rasio publikasi dosen.\n\nProgram studi dengan indikator status watch wajib menyusun rencana tindak lanjut dalam 14 hari kerja.', 1, 22, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 21:49:49'),
(3, 'DOC-RES-01', 5, 'Panduan Hibah Riset & Insentif Publikasi FILKOM', 'Research', 'Panduan_Riset_FILKOM_2026.txt', 'TXT', 232, 'Pusat Riset FILKOM memfasilitasi hibah internal , hibah DRTPM Kemendikbudristek, dan kolaborasi industri. Dosen dengan publikasi Scopus Q1/Q2 atau SINTA 1/2 memperoleh poin kinerja riset dan dukungan pendanaan konferensi IEEE.', 1, 20, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 21:49:49'),
(4, 'DOC-SEC-01', 3, 'SOP Tata Kelola Surat & Rapat Fakultas', 'Administration', 'SOP_Sekretariat_FILKOM.txt', 'TXT', 163, 'Sekretariat FILKOM mengelola penomoran surat resmi fakultas, agenda rapat senat, notulensi rapat koordinasi program studi, dan pengarsipan SK Dekan secara digital.', 1, 1, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 13:41:08'),
(5, 'DOC-EXEC-01', 1, 'Rencana Strategis FILKOM 2025-2029', 'Executive', 'Renstra_FILKOM_2025_2029.txt', 'TXT', 206, 'Renstra FILKOM menargetkan transformasi kampus berbasis AI Orchestration, akreditasi Unggul di seluruh program studi S1 dan S2, peningkatan riset terapan AI & Cybersecurity, serta kesiapan lulusan industri.', 1, 38, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 21:49:49'),
(6, 'DOC-STU-01', 6, 'Buku Panduan Layanan Mahasiswa FILKOM', 'Student Services', 'Panduan_Mahasiswa_FILKOM.txt', 'TXT', 192, 'Mahasiswa dapat berkonsultasi dengan Dosen Penasehat Akademik (PA) sebelum pengisian KRS maksimal 24 SKS sesuai IPS. Layanan beasiswa mencakup Beasiswa Prestasi, KIP-Kuliah, dan Student Labor.', 1, 19, 1, 'admin', '2026-11-24 13:41:08', '2026-11-24 21:49:48');

DROP TABLE IF EXISTS `tbl_knowledge_gaps`;
CREATE TABLE `tbl_knowledge_gaps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `gap_signature` varchar(64) NOT NULL,
  `sample_question` text NOT NULL,
  `sample_variants_json` text DEFAULT NULL,
  `language` varchar(16) NOT NULL DEFAULT 'id',
  `intent_tag` varchar(64) NOT NULL DEFAULT 'general',
  `failure_reason` varchar(120) NOT NULL DEFAULT 'no_local_knowledge',
  `occurrence_count` int(11) NOT NULL DEFAULT 1,
  `avg_eval_score` decimal(4,2) NOT NULL DEFAULT 0.45,
  `negative_feedback_count` int(11) NOT NULL DEFAULT 0,
  `rephrase_count` int(11) NOT NULL DEFAULT 0,
  `stall_count` int(11) NOT NULL DEFAULT 0,
  `status` enum('detected','auto_healed','reinforced','needs_rich_source') NOT NULL DEFAULT 'detected',
  `healing_strategy` varchar(120) DEFAULT NULL,
  `resolved_learned_id` int(11) DEFAULT NULL,
  `suggested_draft` text DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  `healed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gap_sig` (`gap_signature`),
  KEY `idx_gap_status` (`status`,`occurrence_count`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_learned_knowledge`;
CREATE TABLE `tbl_learned_knowledge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `pattern_code` varchar(80) NOT NULL,
  `category` varchar(64) NOT NULL DEFAULT 'Self-Learned',
  `trigger_phrases` text NOT NULL,
  `keywords_json` text DEFAULT NULL,
  `vector_json` longtext DEFAULT NULL,
  `language` enum('id','en','both') NOT NULL DEFAULT 'id',
  `response_id` text NOT NULL,
  `response_en` text DEFAULT NULL,
  `source_type` enum('auto_synthesized','conversation_aligned','kb_alias_expanded','distilled_qa','correction_learned') NOT NULL DEFAULT 'auto_synthesized',
  `source_ref` varchar(255) DEFAULT NULL,
  `confidence_score` decimal(4,3) NOT NULL DEFAULT 0.720,
  `q_value` decimal(5,4) NOT NULL DEFAULT 0.6800,
  `hit_count` int(11) NOT NULL DEFAULT 0,
  `positive_count` int(11) NOT NULL DEFAULT 0,
  `negative_count` int(11) NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `auto_promoted_at` datetime DEFAULT NULL,
  `last_reinforced_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_pattern_code` (`pattern_code`),
  KEY `idx_active_q` (`is_active`,`q_value`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_learning_weights`;
CREATE TABLE `tbl_learning_weights` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `target_type` varchar(32) NOT NULL,
  `target_key` varchar(128) NOT NULL,
  `target_label` varchar(180) DEFAULT NULL,
  `q_value` decimal(5,4) NOT NULL DEFAULT 0.6500,
  `pull_count` int(11) NOT NULL DEFAULT 1,
  `reward_sum` decimal(8,3) NOT NULL DEFAULT 0.650,
  `positive_signals` int(11) NOT NULL DEFAULT 0,
  `negative_signals` int(11) NOT NULL DEFAULT 0,
  `last_reward` decimal(5,3) NOT NULL DEFAULT 0.000,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_key` (`target_type`,`target_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_lecturers`;
CREATE TABLE `tbl_lecturers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nidn` varchar(32) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `study_program_id` int(11) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `academic_rank` varchar(64) DEFAULT 'Lektor',
  `expertise` varchar(180) DEFAULT NULL,
  `teaching_score` decimal(4,2) NOT NULL DEFAULT 4.50,
  `research_score` decimal(4,2) NOT NULL DEFAULT 4.20,
  `status` enum('active','study_leave','inactive') NOT NULL DEFAULT 'active',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_lecturers_nidn` (`nidn`),
  KEY `idx_lecturers_prog` (`study_program_id`,`status`),
  KEY `fk_lect_user` (`user_id`),
  CONSTRAINT `fk_lect_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_lect_user` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

