DROP TABLE IF EXISTS `tbl_login_logs`;
CREATE TABLE `tbl_login_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` varchar(64) DEFAULT NULL,
  `identifier_input` varchar(120) NOT NULL,
  `role_code` varchar(50) DEFAULT NULL,
  `ip_address` varchar(45) NOT NULL,
  `user_agent` varchar(255) DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'SUCCESS',
  `failure_reason` varchar(255) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_login_ip_status` (`ip_address`,`status`,`created_at`),
  KEY `idx_login_user` (`user_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_long_term_memories`;
CREATE TABLE `tbl_long_term_memories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_code` varchar(64) NOT NULL DEFAULT 'DEFAULT',
  `user_identifier` varchar(120) NOT NULL DEFAULT 'Guest',
  `memory_type` enum('preference','fact','project_context','conversation_summary') NOT NULL DEFAULT 'fact',
  `memory_key` varchar(100) NOT NULL,
  `memory_value` text NOT NULL,
  `importance` decimal(3,2) NOT NULL DEFAULT 0.85,
  `access_count` int(11) NOT NULL DEFAULT 1,
  `last_accessed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ltm_sess_type` (`session_code`,`memory_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_meetings`;
CREATE TABLE `tbl_meetings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(180) NOT NULL,
  `meeting_date` datetime NOT NULL,
  `location` varchar(120) NOT NULL,
  `chairperson` varchar(120) NOT NULL,
  `agenda_summary` text NOT NULL,
  `status` enum('scheduled','completed','cancelled') NOT NULL DEFAULT 'scheduled',
  PRIMARY KEY (`id`),
  KEY `idx_meet_date_status` (`meeting_date`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

