DROP TABLE IF EXISTS `tbl_message_attachments`;
CREATE TABLE `tbl_message_attachments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `message_id` int(11) NOT NULL,
  `file_name` varchar(180) NOT NULL,
  `file_type` varchar(24) NOT NULL,
  `file_size_bytes` int(11) NOT NULL DEFAULT 0,
  `storage_path` varchar(255) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ma_msg` (`message_id`),
  CONSTRAINT `fk_ma_msg` FOREIGN KEY (`message_id`) REFERENCES `tbl_messages` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_messages`;
CREATE TABLE `tbl_messages` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `conversation_id` int(11) NOT NULL,
  `sender_type` enum('user','agent','orchestrator','system') NOT NULL DEFAULT 'user',
  `agent_id` int(11) DEFAULT NULL,
  `content` longtext NOT NULL,
  `metadata_json` text DEFAULT NULL,
  `citations_json` text DEFAULT NULL,
  `satisfaction_rating` tinyint(1) DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_msg_conv_created` (`conversation_id`,`created_at`),
  KEY `fk_msg_agent` (`agent_id`),
  CONSTRAINT `fk_msg_agent` FOREIGN KEY (`agent_id`) REFERENCES `tbl_agents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_msg_conv` FOREIGN KEY (`conversation_id`) REFERENCES `tbl_conversations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_permissions`;
CREATE TABLE `tbl_permissions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `permission_code` varchar(64) NOT NULL,
  `permission_name` varchar(120) NOT NULL,
  `module` varchar(64) NOT NULL,
  `description` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_permissions_code` (`permission_code`),
  KEY `idx_perm_module` (`module`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_permissions` (`id`, `permission_code`, `permission_name`, `module`, `description`) VALUES
