(9, 'agents.approve', 'Approve AI-Generated Agents', 'agents', 'Review and activate AI-generated agents'),
(10, 'agents.use', 'Invoke Authorized Agents', 'orchestrator', 'Interact with authorized agents via Orchestrator'),
(11, 'tools.manage', 'Manage Agent Tools', 'tools', 'Configure and toggle tool registry permissions'),
(12, 'knowledge.manage', 'Manage Knowledge & RAG', 'knowledge', 'Upload, index, and manage RAG knowledge bases and ACLs'),
(13, 'knowledge.read', 'Read Authorized Knowledge', 'knowledge', 'Query role-authorized RAG knowledge documents'),
(14, 'monitoring.view', 'View Agent Monitoring', 'monitoring', 'Inspect agent execution metrics and activity timeline'),
(15, 'api_keys.manage', 'Manage OpenAI/LLM Keys & Usage', 'system', 'Manage encrypted provider keys and view token costs'),
(16, 'audit.view', 'View Audit & Security Logs', 'security', 'Inspect audit logs and WAF security incidents'),
(17, 'scope.all_faculty', 'Faculty-Wide Executive Scope', 'scope', 'Access aggregated faculty-wide metrics across all programs'),
(18, 'scope.own_program', 'Study Program Scope', 'scope', 'Access academic data strictly for assigned study program'),
(19, 'scope.own_student', 'Personal Student Scope', 'scope', 'Access strictly own student academic, schedule, attendance & thesis records'),
(20, 'scope.administration', 'Faculty Administration Scope', 'scope', 'Access faculty correspondence, meetings, and admin documents'),
(21, 'scope.quality_assurance', 'Quality Assurance Scope', 'scope', 'Access UPMF KPIs, internal audits, and accreditation evidence'),
(22, 'scope.research', 'Research Chair Scope', 'scope', 'Access research projects, funding, and lecturer publications');

DROP TABLE IF EXISTS `tbl_publications`;
CREATE TABLE `tbl_publications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `lecturer_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `venue` varchar(160) NOT NULL,
  `index_tier` enum('Scopus Q1','Scopus Q2','Scopus Q3','SINTA 1','SINTA 2','IEEE Conference') NOT NULL DEFAULT 'SINTA 2',
  `year` int(11) NOT NULL DEFAULT 2026,
  `citations` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_pub_lect_year` (`lecturer_id`,`year`),
  CONSTRAINT `fk_pub_lect` FOREIGN KEY (`lecturer_id`) REFERENCES `tbl_lecturers` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_publications` (`id`, `lecturer_id`, `title`, `venue`, `index_tier`, `year`, `citations`) VALUES
