  CONSTRAINT `fk_rp_lect` FOREIGN KEY (`lead_lecturer_id`) REFERENCES `tbl_lecturers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_rp_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

