DROP TABLE IF EXISTS `tbl_rl_agent_models`;
CREATE TABLE `tbl_rl_agent_models` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `model_code` varchar(32) NOT NULL,
  `training_session_id` int(11) DEFAULT NULL,
  `model_name` varchar(150) NOT NULL,
  `version` varchar(32) NOT NULL DEFAULT '1.0.0',
  `algorithm` varchar(48) NOT NULL DEFAULT 'BEHAVIOR_CLONING',
  `state_dim` int(11) NOT NULL DEFAULT 14,
  `action_dim` int(11) NOT NULL DEFAULT 9,
  `architecture_json` text DEFAULT NULL,
  `normalization_json` text DEFAULT NULL,
  `metrics_json` text DEFAULT NULL,
  `file_path` varchar(255) NOT NULL,
  `file_size_bytes` int(11) NOT NULL DEFAULT 0,
  `checksum_sha256` varchar(64) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ram_code` (`model_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_rl_demo_annotations`;
CREATE TABLE `tbl_rl_demo_annotations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demonstration_id` int(11) NOT NULL,
  `episode_id` int(11) NOT NULL DEFAULT 1,
  `step_start` int(11) NOT NULL DEFAULT 0,
  `step_end` int(11) NOT NULL DEFAULT 0,
  `label` varchar(80) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rda_demo` (`demonstration_id`),
  CONSTRAINT `fk_rda_demo` FOREIGN KEY (`demonstration_id`) REFERENCES `tbl_rl_demonstrations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_rl_demo_transitions`;
CREATE TABLE `tbl_rl_demo_transitions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demonstration_id` int(11) NOT NULL,
  `episode_id` int(11) NOT NULL DEFAULT 1,
  `step_number` int(11) NOT NULL DEFAULT 1,
  `timestamp_ms` bigint(20) NOT NULL DEFAULT 0,
  `state_json` text NOT NULL,
  `action` int(11) NOT NULL DEFAULT 0,
  `confidence` decimal(5,4) NOT NULL DEFAULT 1.0000,
  `reward` decimal(8,4) NOT NULL DEFAULT 0.0000,
  `next_state_json` text NOT NULL,
  `done` tinyint(1) NOT NULL DEFAULT 0,
  `flag_corner` varchar(8) NOT NULL DEFAULT 'NE',
  PRIMARY KEY (`id`),
  KEY `idx_rdt_demo_step` (`demonstration_id`,`episode_id`,`step_number`),
  CONSTRAINT `fk_rdt_demo` FOREIGN KEY (`demonstration_id`) REFERENCES `tbl_rl_demonstrations` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_rl_demonstrations`;
CREATE TABLE `tbl_rl_demonstrations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `demo_code` varchar(32) NOT NULL,
  `session_id` int(11) DEFAULT NULL,
  `title` varchar(160) NOT NULL,
  `demonstrator_name` varchar(100) NOT NULL DEFAULT 'FILKOM Lab',
  `input_source` enum('webcam','keyboard','hybrid') NOT NULL DEFAULT 'webcam',
  `flag_corner_code` varchar(8) NOT NULL DEFAULT 'NE',
  `episode_count` int(11) NOT NULL DEFAULT 1,
  `total_steps` int(11) NOT NULL DEFAULT 0,
  `total_reward` decimal(10,2) NOT NULL DEFAULT 0.00,
  `success_episodes` int(11) NOT NULL DEFAULT 0,
  `success_rate` decimal(5,2) NOT NULL DEFAULT 0.00,
  `avg_confidence` decimal(5,3) NOT NULL DEFAULT 0.850,
  `state_dim` int(11) NOT NULL DEFAULT 14,
  `action_dim` int(11) NOT NULL DEFAULT 9,
  `sample_rate_hz` decimal(5,2) NOT NULL DEFAULT 8.00,
  `calibration_json` text DEFAULT NULL,
  `action_distribution_json` text DEFAULT NULL,
  `status` enum('recording','saved','archived') NOT NULL DEFAULT 'saved',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rl_demo_code` (`demo_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_rl_training_metrics`;
CREATE TABLE `tbl_rl_training_metrics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `training_session_id` int(11) NOT NULL,
  `epoch` int(11) NOT NULL,
  `loss` decimal(10,6) NOT NULL,
  `accuracy` decimal(6,4) NOT NULL,
  `val_loss` decimal(10,6) DEFAULT NULL,
  `val_accuracy` decimal(6,4) DEFAULT NULL,
  `learning_rate` decimal(10,8) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_rtm_sess_epoch` (`training_session_id`,`epoch`),
  CONSTRAINT `fk_rtm_sess` FOREIGN KEY (`training_session_id`) REFERENCES `tbl_rl_training_sessions` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_rl_training_sessions`;
CREATE TABLE `tbl_rl_training_sessions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `training_code` varchar(32) NOT NULL,
  `demonstration_ids_json` text DEFAULT NULL,
  `model_name` varchar(150) NOT NULL DEFAULT 'KungfuNet-BC',
  `architecture_json` text DEFAULT NULL,
  `hyperparams_json` text DEFAULT NULL,
  `normalization_json` text DEFAULT NULL,
  `total_samples` int(11) NOT NULL DEFAULT 0,
  `train_samples` int(11) NOT NULL DEFAULT 0,
  `val_samples` int(11) NOT NULL DEFAULT 0,
  `epochs_planned` int(11) NOT NULL DEFAULT 50,
  `epochs_completed` int(11) NOT NULL DEFAULT 0,
  `class_distribution_json` text DEFAULT NULL,
  `final_loss` decimal(10,6) DEFAULT NULL,
  `final_val_loss` decimal(10,6) DEFAULT NULL,
  `final_accuracy` decimal(6,4) DEFAULT NULL,
  `final_val_accuracy` decimal(6,4) DEFAULT NULL,
  `confusion_matrix_json` text DEFAULT NULL,
  `status` enum('running','completed','cancelled','failed') NOT NULL DEFAULT 'running',
  `error_message` text DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `completed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rts_code` (`training_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

