  `stall_rate` decimal(5,2) NOT NULL DEFAULT 0.00,
  `summary_note` text DEFAULT NULL,
  `duration_ms` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_static_knowledge`;
CREATE TABLE `tbl_static_knowledge` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `topic_code` varchar(64) NOT NULL,
  `category` varchar(64) NOT NULL DEFAULT 'General',
  `keywords_id` text NOT NULL,
  `keywords_en` text NOT NULL,
  `response_id` text NOT NULL,
  `response_en` text NOT NULL,
  `expression` varchar(32) NOT NULL DEFAULT 'HAPPY',
  `gesture` varchar(32) NOT NULL DEFAULT 'NONE',
  `priority` int(11) NOT NULL DEFAULT 10,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `hit_count` int(11) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sk_topic` (`topic_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tbl_static_knowledge` (`id`, `topic_code`, `category`, `keywords_id`, `keywords_en`, `response_id`, `response_en`, `expression`, `gesture`, `priority`, `is_active`, `hit_count`, `created_at`) VALUES
(1, 'identity', 'Identitas', 'siapa kamu,nama kamu,filkom orchestrator,robot,perkenalkan diri', 'who are you,your name,filkom orchestrator,introduce yourself', 'Saya FILKOM AI Agent Orchestrator Universitas, ekosistem multi-agen cerdas untuk layanan akademik dan tata kelola fakultas.', 'I am the FILKOM AI Agent Orchestrator at Universitas, a role-based multi-agent intelligence platform.', 'HAPPY', 'WAVE', 100, 1, 1, '2026-11-24 13:41:08'),
(2, 'greeting_general', 'Sapaan', 'halo,hai,hello,hi,syalom,shalom,selamat pagi,selamat siang', 'hello,hi,good morning,good afternoon,greetings', 'Halo! Saya siap mengoordinasikan agen AI FILKOM sesuai peran Anda.', 'Hello! I am ready to coordinate FILKOM AI agents for your authorized role.', 'HAPPY', 'WAVE', 95, 1, 1, '2026-11-24 13:41:08'),
(3, 'filkom_info', 'Kampus', 'filkom,fakultas ilmu komputer,informatika,sistem informasi,teknologi informasi,magister sistem informasi', 'filkom,computer science,informatics,information systems,information technology', 'FILKOM  membina Prodi S1 Informatika, S1 Sistem Informasi, S1 Teknologi Informasi, dan S2 Magister Sistem Informasi.', 'FILKOM  offers B.S. Informatics, B.S. Information Systems, B.S. Information Technology, and M.S. Information Systems.', 'SMILING', 'EXPLAIN', 90, 1, 1, '2026-11-24 13:41:08'),
(6, 'greeting_morning', 'Sapaan', 'selamat pagi,pagi bu,pagi dosen,pagi ot', 'good morning,morning lecturer,morning ot', 'Selamat pagi! Ada yang bisa saya bantu?', 'Good morning! How can I help you?', 'HAPPY', 'WAVE', 94, 1, 1, '2026-11-24 13:41:08'),
(7, 'greeting_afternoon', 'Sapaan', 'selamat siang,siang bu,siang dosen,selamat sore,sore bu', 'good afternoon,afternoon lecturer,good evening', 'Selamat siang! Ada yang bisa saya bantu?', 'Good afternoon! How can I help you?', 'HAPPY', 'WAVE', 94, 1, 0, '2026-11-24 13:41:08'),
(8, 'greeting_night', 'Sapaan', 'selamat malam,malam bu,malam dosen,lembur', 'good night,working late,evening ot', 'Selamat malam! Ada yang bisa saya bantu?', 'Good evening! How can I help you?', 'SMILING', 'NOD', 94, 1, 0, '2026-11-24 13:41:08'),
(9, 'how_are_you', 'Sapaan', 'apa kabar,kabar kamu,gimana kabarnya,sehat bu', 'how are you,how do you feel,how is it going,are you well', 'Saya baik, terima kasih. Bagaimana kabar Anda?', 'I\'m doing well, thanks. How are you?', 'HAPPY', 'NOD', 92, 1, 2, '2026-11-24 13:41:08'),
(10, 'gratitude', 'Etika', 'terima kasih,makasih,thanks,thank you,mantap,keren,bagus sekali,hebat', 'thank you,thanks,awesome,great job,amazing,helpful,appreciate it', 'Sama-sama! Silakan tanya lagi jika perlu.', 'You\'re welcome! Feel free to ask anytime.', 'HAPPY', 'BOW', 92, 1, 0, '2026-11-24 13:41:08'),
(11, 'goodbye', 'Etika', 'sampai jumpa,dadah,bye,pamit dulu,selesai dulu', 'goodbye,bye,see you later,take care,signing off', 'Sampai jumpa! Semoga harimu menyenangkan.', 'Goodbye! Have a great day.', 'HAPPY', 'WAVE', 91, 1, 0, '2026-11-24 13:41:08'),
(12, 'capabilities', 'Sistem', 'bisa apa,fitur kamu,kemampuan kamu,cara pakai,fungsi ot', 'what can you do,your features,capabilities,how to use,functions', 'Saya bisa chat ID/EN, mencari dokumen RAG, menjalankan 100 function tools, lip-sync, dan aksi 3D.', 'I support bilingual chat, RAG document search, 100 function tools, lip-sync, and 3D animations.', 'SMILING', 'EXPLAIN', 90, 1, 0, '2026-11-24 13:41:08'),
(13, '_profile', 'Kampus ', ',universitas,tentang ,alamat ,di mana ,dimana ,lokasi kampus', ',university,about ,where is ,campus location', 'Universitas (test) berlokasi di Airmadidi, Minahasa Utara, Sulawesi Utara, berdiri sejak 1965.', 'University (test) is located in Airmadidi, North Minahasa, North Sulawesi, founded in 1965.', 'HAPPY', 'EXPLAIN', 89, 1, 1, '2026-11-24 13:41:08'),
(14, '_faculties', 'Kampus ', 'fakultas di ,jurusan di ,program studi,prodi ', 'faculties at ,majors at ,study programs,departments', ' memiliki FILKOM, FEB, Filsafat, FKIP, Pertanian, Keperawatan, ASMI, dan Pascasarjana.', ' has FILKOM, FEB, Philosophy, Education, Agriculture, Nursing, ASMI, and Graduate School.', 'SMILING', 'EXPLAIN', 88, 1, 0, '2026-11-24 13:41:08'),
(16, 'ai_lab', 'Akademik & AI', 'laboratorium ai,lab robotika,lab kecerdasan buatan,riset ai', 'ai lab,robotics lab,artificial intelligence laboratory,ai research', 'Lab AI & Robotika FILKOM  meneliti Reinforcement Learning, 3D Virtual Assistant, Vision, dan NLP.', 'The FILKOM AI & Robotics Lab develops Reinforcement Learning, 3D Assistant, Vision, and NLP projects.', 'HAPPY', 'EXPLAIN', 87, 1, 0, '2026-11-24 13:41:08'),
(17, 'reinforcement_learning', 'Akademik & AI', 'apa itu reinforcement learning,jelaskan rl,q-learning,dqn,ppo,reward agent', 'what is reinforcement learning,explain rl,deep q network,policy gradient', 'Reinforcement Learning melatih agen mengambil keputusan lewat interaksi dan reward dari lingkungan.', 'Reinforcement Learning trains an agent to make optimal decisions through environment rewards.', 'THINKING', 'EXPLAIN', 86, 1, 0, '2026-11-24 13:41:08'),
(18, 'imitation_learning', 'Akademik & AI', 'imitation learning,behavior cloning,belajar dari demonstrasi', 'imitation learning,behavior cloning,learning from demonstration', 'Imitation Learning melatih agen meniru kebijakan langsung dari demonstrasi manusia atau pakar.', 'Imitation Learning trains an agent by mimicking expert or human demonstrations directly.', 'SMILING', 'EXPLAIN', 85, 1, 0, '2026-11-24 13:41:08'),
(19, 'rag_concept', 'Akademik & AI', 'apa itu rag,retrieval augmented generation,cara kerja rag', 'what is rag,retrieval augmented generation,how rag works', 'RAG menggabungkan pencarian dokumen internal dengan LLM agar jawaban lebih akurat dan bersumber.', 'RAG combines document search with an LLM so answers stay accurate and cite their sources.', 'SMILING', 'EXPLAIN', 85, 1, 0, '2026-11-24 13:41:08'),
(20, 'llm_gemini', 'Akademik & AI', 'apa itu gemini,google gemini,llm,large language model', 'what is gemini,google gemini api,large language model', 'Google Gemini adalah model AI multimodal yang dipakai ot untuk penalaran dan percakapan.', 'Google Gemini is a multimodal AI model integrated into ot for reasoning and chat.', 'HAPPY', 'NOD', 85, 1, 0, '2026-11-24 13:41:08'),
(21, 'academic_calendar', 'Layanan Kampus', 'kalender akademik,kapan kuliah dimulai,semester ganjil,semester genap,jadwal uts,jadwal uas', 'academic calendar,when does semester start,midterm schedule,final exam', 'Semester Ganjil berlangsung Agustus–Desember, Genap Januari–Mei, dan Semester Padat Juni–Juli.', 'Odd Semester runs Aug–Dec, Even Semester Jan–May, and Short Semester takes place in Jun–Jul.', 'SMILING', 'EXPLAIN', 84, 1, 1, '2026-11-24 13:41:08'),
(22, 'scholarship_info', 'Layanan Kampus', 'beasiswa,potongan uang kuliah,bantuan biaya,kip kuliah,student labor', 'scholarship,financial aid,tuition discount,student labor program', ' menyediakan Beasiswa Prestasi, KIP-Kuliah, Beasiswa Yayasan, dan program Student Labor.', ' offers Merit Scholarships, KIP-Kuliah, Foundation Aid, and Student Labor.', 'HAPPY', 'NOD', 84, 1, 0, '2026-11-24 13:41:08'),
(23, 'dormitory_info', 'Layanan Kampus', 'asrama,boarding,aturan asrama,jam malam asrama,crystal,jasmine,edelweiss', 'dormitory,campus housing,dorm rules,curfew', ' menyediakan asrama putra dan putri dengan pembinaan rutin serta jam tenang mulai pukul 21.30 WITA.', ' provides men\'s and women\'s dormitories with evening quiet hours starting at 9:30 PM.', 'SMILING', 'NOD', 83, 1, 1, '2026-11-24 13:41:08'),
