(25, 'tuition_payment', 'Layanan Kampus', 'pembayaran ukt,biaya kuliah,uang kuliah,business office,virtual account', 'tuition payment,school fee,business office,how to pay tuition', 'Pembayaran kuliah dilakukan lewat Virtual Account bank mitra atau konfirmasi ke Business Office.', 'Tuition is paid via partner bank Virtual Accounts or confirmed at the Business Office.', 'SMILING', 'EXPLAIN', 82, 1, 0, '2026-11-24 13:41:08'),
(26, 'dress_code', 'Layanan Kampus', 'aturan berpakaian,seragam kuliah,dress code kampus,pakaian rapi', 'dress code,campus attire,uniform rules', 'Mahasiswa wajib berpakaian rapi dan sopan: pria berkemeja dan celana kain, wanita busana sopan.', 'Students must dress neatly: collared shirts and slacks for men, modest attire for women.', 'SMILING', 'NOD', 82, 1, 0, '2026-11-24 13:41:08'),
(27, 'thesis_skripsi', 'Akademik & AI', 'skripsi,tugas akhir,proposal skripsi,syarat sidang,pembimbing skripsi', 'thesis,final project,capstone project,thesis defense', 'Syarat ambil Skripsi: minimal 120 SKS lulus, lulus Metodologi Penelitian, dan persetujuan Kaprodi.', 'Thesis requires at least 120 completed credits, passing Research Methodology, and program approval.', 'THINKING', 'EXPLAIN', 82, 1, 3, '2026-11-24 13:41:08'),
(28, 'krs_enrollment', 'Layanan Kampus', 'cara isi krs,kartu rencana studi,batas sks,konsultasi pa,penasehat akademik', 'course registration,krs,credit limit,academic advisor', 'KRS diisi di portal akademik maksimal 24 SKS sesuai IPS sebelumnya dan wajib disetujui dosen PA.', 'KRS is filled online up to 24 credits based on prior GPA and requires Academic Advisor approval.', 'SMILING', 'EXPLAIN', 81, 1, 0, '2026-11-24 13:41:08'),
(29, 'grading_system', 'Akademik & AI', 'sistem nilai,ipk,cara hitung ipk,nilai a b c,bobot nilai', 'grading system,gpa calculation,grade points', 'Skala nilai : A (4.0), A- (3.7), B+ (3.3), B (3.0), B- (2.7), C+ (2.3), C (2.0), D (1.0), E (0.0).', ' uses a 4.00 scale: A (4.0), A- (3.7), B+ (3.3), B (3.0), B- (2.7), C+ (2.3), C (2.0), D (1.0), E (0.0).', 'SMILING', 'EXPLAIN', 81, 1, 0, '2026-11-24 13:41:08'),
(30, 'attendance_rule', 'Layanan Kampus', 'batas absen,kehadiran kuliah,minimal kehadiran,presensi', 'attendance policy,maximum absences,class attendance', 'Mahasiswa wajib hadir minimal 80% per mata kuliah agar bisa mengikuti UAS.', 'Students need at least 80% class attendance per course to take the Final Exam.', 'SMILING', 'NOD', 81, 1, 0, '2026-11-24 13:41:08'),
(31, 'webcam_feature', 'Sistem', 'cara pakai webcam,ikuti gerakan,motion tracking,movenet,mediapipe', 'how to use webcam,motion tracking,pose imitation,hand tracking', 'Aktifkan \'Ikuti Gerakan via Webcam\' di Pengaturan agar avatar meniru pose dan jari tangan Anda.', 'Enable \'Follow Motion via Webcam\' in Settings so the avatar mirrors your body and hands.', 'HAPPY', 'EXPLAIN', 80, 1, 0, '2026-11-24 13:41:08'),
