(33, 'custom_outfit_info', 'Sistem', 'ganti baju,ganti kostum,kacamata,ganti background,latar belakang 3d', 'change outfit,eyewear,glasses,change 3d background', 'Anda bisa mengganti 6 jas, 10 kacamata 3D, dan 6 ruang latar melalui menu Pengaturan.', 'You can switch 6 outfits, 10 3D glasses, and 6 3D rooms in the Settings menu.', 'HAPPY', 'NOD', 80, 1, 0, '2026-11-24 13:41:08'),
(34, 'security_info', 'Sistem', 'keamanan sistem,apakah aman,proteksi waf,enkripsi data', 'system security,is it secure,waf protection,encryption', 'Sistem dilindungi WAF, CSRF token, bcrypt, enkripsi API Key AES-256, rate limit, dan audit log.', 'The app uses WAF filtering, CSRF tokens, bcrypt, AES-256 key encryption, rate limits, and audit logs.', 'SMILING', 'NOD', 80, 1, 0, '2026-11-24 13:41:08'),
(35, 'creator_team', 'Identitas', 'siapa pembuatmu,siapa yang buat,developer ot,tim pengembang,siapa pencipta kamu,siapa penciptamu,pencipta kamu,siapa yang menciptakanmu', 'who created you,who built you,your developer,author,who made you,who is your creator', 'Saya dibuat oleh tim Lab AI & Robotika FILKOM Universitas.', 'I was built by the AI & Robotics Lab team at FILKOM, University.', 'HAPPY', 'BOW', 85, 1, 0, '2026-11-24 13:41:08'),
(36, 'python_programming', 'Akademik & AI', 'belajar python,bahasa python,kenapa python populer untuk ai', 'learn python,why python for ai,python programming', 'Python populer di AI karena sintaksnya ringkas dan didukung pustaka seperti PyTorch dan TensorFlow.', 'Python is popular for AI due to its clean syntax and libraries like PyTorch and TensorFlow.', 'SMILING', 'EXPLAIN', 79, 1, 1, '2026-11-24 13:41:08'),
(37, 'threejs_webgl', 'Akademik & AI', 'three.js,webgl,bagaimana avatar 3d dibuat,model glb', 'how is 3d avatar made,threejs,webgl rendering,glb model', 'Avatar 3D dirender di browser memakai Three.js WebGL dengan rig tulang dan morph target wajah.', 'The 3D avatar runs in the browser via Three.js WebGL with bone rigging and facial morph targets.', 'HAPPY', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(38, 'sql_database', 'Akademik & AI', 'apa itu sql,belajar database,mysql,normalisasi database', 'what is sql,database normalization,mysql database', 'SQL dipakai mengelola database relasional seperti MySQL; SQL Assistant siap bantu kueri aman.', 'SQL manages relational databases like MySQL; use my SQL Assistant for safe queries.', 'SMILING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(39, 'study_tips', 'Motivasi', 'tips belajar,cara fokus belajar,agar tidak malas,tips cepat paham', 'study tips,how to focus,effective learning,exam preparation', 'Gunakan teknik Pomodoro (25 menit fokus, 5 menit jeda), ringkas materi, dan langsung praktik.', 'Use Pomodoro (25m focus, 5m break), summarize concepts, and practice with small projects.', 'HAPPY', 'NOD', 78, 1, 0, '2026-11-24 13:41:08'),
(40, 'motivation_sad', 'Emosi & Empati', 'sedih,capek,lelah,galau,stres,pusing,putus asa,burnout', 'sad,tired,exhausted,stressed,overwhelmed,burnout,upset', 'Tetap semangat, ya. Istirahat sejenak kalau lelah, lalu lanjut lagi pelan-pelan.', 'Hang in there. Take a short break if you\'re tired, then continue step by step.', 'SAD', 'NOD', 88, 1, 7, '2026-11-24 13:41:08'),
