(72, 'rnn_lstm', 'Akademik & AI', 'apa itu rnn,lstm,gru,data sekuensial,time series', 'what is rnn,lstm network,sequence modeling,time series', 'RNN dan LSTM memproses data berurutan seperti teks atau deret waktu dengan memori konteks.', 'RNNs and LSTMs process sequential data like text or time series while keeping prior context.', 'THINKING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(73, 'transformer_arch', 'Akademik & AI', 'apa itu transformer,self attention,mekanisme atensi,bert,gpt', 'what is transformer,self attention mechanism,attention is all you need', 'Transformer memakai Self-Attention untuk memahami hubungan antar kata secara paralel pada LLM.', 'Transformers use Self-Attention to model word relationships in parallel, powering modern LLMs.', 'HAPPY', 'EXPLAIN', 81, 1, 0, '2026-11-24 13:41:08'),
(74, 'prompt_engineering', 'Akademik & AI', 'prompt engineering,cara membuat prompt bagus,few shot,chain of thought', 'prompt engineering,good prompts,few shot prompting,chain of thought', 'Prompt yang jelas mencantumkan peran, konteks, batasan format, serta contoh jika diperlukan.', 'Good prompts define a clear role, context, output constraints, and examples when needed.', 'HAPPY', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(75, 'fine_tuning_vs_rag', 'Akademik & AI', 'bedanya fine tuning dan rag,kapan pakai rag,fine tuning llm', 'fine tuning vs rag,when to use rag,customize llm', 'RAG cocok untuk fakta terbaru dengan sitasi sumber; Fine-Tuning untuk membentuk gaya atau domain.', 'RAG suits up-to-date facts with citations; Fine-Tuning adapts model style or specialized behavior.', 'THINKING', 'EXPLAIN', 80, 1, 0, '2026-11-24 13:41:08'),
(76, 'tfidf_cosine', 'Akademik & AI', 'tf idf,cosine similarity,pencarian vektor,pencocokan dokumen', 'tf idf,cosine similarity,vector similarity,document ranking', 'TF-IDF memberi bobot kata penting, lalu Cosine Similarity mengukur kemiripan sudut antar vektor.', 'TF-IDF weights key terms, and Cosine Similarity measures the angle similarity between vectors.', 'SMILING', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(77, 'mdp_rl', 'Akademik & AI', 'markov decision process,mdp,state action reward,diskon gamma', 'markov decision process,state space,action space,discount factor', 'MDP memodelkan keputusan berurutan lewat State, Action, Transition, Reward, dan faktor diskon gamma.', 'MDP models sequential decisions using States, Actions, Transitions, Rewards, and discount gamma.', 'THINKING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(78, 'q_learning', 'Akademik & AI', 'q learning,bellman equation,tabel q,off policy rl', 'q learning,bellman equation,q value,off policy learning', 'Q-Learning memperbarui nilai aksi Q(s,a) lewat persamaan Bellman untuk memilih aksi terbaik.', 'Q-Learning updates action-value Q(s,a) via the Bellman equation to pick optimal actions.', 'THINKING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(79, 'ppo_rl', 'Akademik & AI', 'ppo,proximal policy optimization,policy gradient,actor critic', 'ppo,proximal policy optimization,actor critic,rlhf', 'PPO menjaga pembaruan kebijakan RL tetap stabil memakai clipped objective.', 'PPO stabilizes RL policy updates using a clipped surrogate objective.', 'SMILING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(80, 'exploration_exploitation', 'Akademik & AI', 'exploration exploitation,epsilon greedy,dilema eksplorasi', 'exploration vs exploitation,epsilon greedy,multi armed bandit', 'Exploration vs Exploitation menyeimbangkan mencoba aksi baru dan memilih aksi terbaik yang sudah ada.', 'Exploration vs Exploitation balances trying new actions against using the best known one.', 'THINKING', 'EXPLAIN', 77, 1, 0, '2026-11-24 13:41:08'),
(81, 'mediapipe_movenet', 'Akademik & AI', 'cara kerja movenet,mediapipe hands,pose estimation,keypoint tubuh', 'how movenet works,mediapipe hands,pose keypoint estimation', 'MoveNet melacak 17 titik tubuh dan MediaPipe Hands melacak 21 titik per telapak tangan di browser.', 'MoveNet tracks 17 body keypoints and MediaPipe Hands tracks 21 hand landmarks in the browser.', 'HAPPY', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(82, 'blendshapes_lipsync', 'Akademik & AI', 'cara kerja lip sync,viseme,morph target,blendshape wajah', 'how lip sync works,viseme mapping,facial blendshapes', 'Lip-sync memetakan fonem ucapan ke bobot morph target mulut wajah 3D saat suara diputar.', 'Lip-sync maps spoken phonemes to 3D facial mouth blendshapes synchronized with TTS audio.', 'SMILING', 'EXPLAIN', 80, 1, 0, '2026-11-24 13:41:08'),
(83, 'web_speech_api', 'Akademik & AI', 'web speech api,speech synthesis,speech recognition,suara avatar', 'web speech api,text to speech,speech to text,browser voice', 'Web Speech API menyediakan SpeechRecognition untuk input suara dan SpeechSynthesis untuk TTS.', 'The Web Speech API provides SpeechRecognition for voice input and SpeechSynthesis for TTS.', 'SMILING', 'EXPLAIN', 77, 1, 0, '2026-11-24 13:41:08');
INSERT INTO `tbl_static_knowledge` (`id`, `topic_code`, `category`, `keywords_id`, `keywords_en`, `response_id`, `response_en`, `expression`, `gesture`, `priority`, `is_active`, `hit_count`, `created_at`) VALUES
(84, 'cloud_computing', 'Akademik & AI', 'cloud computing,aws,gcp,azure,iaas paas saas', 'cloud computing,iaas paas saas,cloud architecture', 'Cloud Computing menyediakan sumber daya komputasi sesuai permintaan dalam model IaaS, PaaS, dan SaaS.', 'Cloud Computing delivers on-demand computing resources across IaaS, PaaS, and SaaS.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(85, 'docker_containers', 'Akademik & AI', 'docker,container,kubernetes,virtualisasi aplikasi', 'docker,containers,microservices,kubernetes', 'Docker mengemas aplikasi beserta dependensinya ke dalam kontainer ringan yang portabel.', 'Docker packages apps and dependencies into lightweight, portable containers.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(86, 'git_version_control', 'Akademik & AI', 'belajar git,github,commit push pull,branching git', 'git version control,github workflow,branch merge commit', 'Git melacak riwayat perubahan kode dengan commit dan branch agar kolaborasi tim lebih rapi.', 'Git tracks code history using commits and branches for clean team collaboration.', 'HAPPY', 'NOD', 77, 1, 0, '2026-11-24 13:41:08'),
(87, 'rest_api_json', 'Akademik & AI', 'apa itu rest api,json,http get post,endpoint api', 'what is rest api,json payload,http methods', 'REST API memakai metode HTTP (GET, POST, PUT, DELETE) dengan pertukaran data JSON.', 'REST APIs use standard HTTP methods (GET, POST, PUT, DELETE) with JSON payloads.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(88, 'mvc_architecture', 'Akademik & AI', 'pola mvc,model view controller,struktur projek php', 'mvc pattern,model view controller,php architecture', 'Pola MVC memisahkan logika data (Model), tampilan (View), dan pengendali alur (Controller).', 'MVC separates data logic (Model), user interface (View), and request flow (Controller).', 'SMILING', 'EXPLAIN', 77, 1, 0, '2026-11-24 13:41:08'),
(89, 'cyber_sqli', 'Keamanan Siber', 'sql injection,sqli,prepared statement,pdo parameter binding', 'sql injection prevention,prepared statements,pdo', 'SQL Injection dicegah memakai PDO Prepared Statements dengan parameter terikat.', 'SQL Injection is prevented by using parameterized PDO Prepared Statements.', 'SMILING', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(90, 'cyber_xss_csp', 'Keamanan Siber', 'xss,cross site scripting,content security policy,csp,htmlspecialchars', 'xss prevention,content security policy,output escaping', 'XSS dicegah lewat encoding output (htmlspecialchars/textContent) dan header CSP.', 'XSS is prevented through output escaping (htmlspecialchars/textContent) and CSP headers.', 'SMILING', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(91, 'cyber_csrf', 'Keamanan Siber', 'csrf token,cross site request forgery,keamanan form', 'csrf protection,synchronizer token,form security', 'CSRF dicegah memakai token unik per sesi yang diverifikasi pada tiap permintaan POST/PUT/DELETE.', 'CSRF is blocked using per-session tokens verified on state-changing requests.', 'SMILING', 'NOD', 78, 1, 0, '2026-11-24 13:41:08'),
(92, 'cyber_bcrypt', 'Keamanan Siber', 'bcrypt,password hash,kenapa password harus di hash,salt password', 'bcrypt hashing,password security,password_verify', 'Kata sandi di-hash satu arah dengan PASSWORD_BCRYPT dan diverifikasi lewat password_verify.', 'Passwords are hashed with PASSWORD_BCRYPT and checked using timing-safe password_verify.', 'SMILING', 'NOD', 78, 1, 0, '2026-11-24 13:41:08'),
(93, 'cyber_aes256', 'Keamanan Siber', 'aes 256,enkripsi api key,aes-256-cbc,keamanan kunci api', 'aes 256 encryption,api key security,encrypt secrets', 'API Key dienkripsi di server memakai AES-256-CBC dengan IV acak sebelum disimpan ke MySQL.', 'API keys are encrypted server-side with AES-256-CBC and a random IV before MySQL storage.', 'SMILING', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(94, 'cyber_ssrf', 'Keamanan Siber', 'ssrf,server side request forgery,validasi url eksternal', 'ssrf protection,validate external url,private ip block', 'Proteksi SSRF memvalidasi skema HTTPS dan memblokir alamat loopback serta IP privat.', 'SSRF protection enforces HTTPS and blocks loopback or private IP addresses.', 'SMILING', 'NOD', 77, 1, 0, '2026-11-24 13:41:08'),
(95, 'cyber_rbac', 'Keamanan Siber', 'rbac,role based access control,admin operator auditor,hak akses', 'rbac,role permissions,admin operator auditor', 'RBAC membagi hak akses menjadi 3 peran: Admin (penuh), Operator (AI & KB), dan Auditor (baca saja).', 'RBAC enforces three roles: Admin (full), Operator (AI & KB), and Auditor (read-only).', 'SMILING', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(96, 'cyber_lockout', 'Keamanan Siber', 'brute force login,terkunci 5 kali,rate limiting login', 'brute force protection,account lockout,rate limiting', 'Login dibatasi maksimal 5 percobaan gagal sebelum akun dikunci sementara selama 15 menit.', 'Login locks accounts for 15 minutes after 5 consecutive failed attempts.', 'SMILING', 'NOD', 77, 1, 0, '2026-11-24 13:41:08'),
(97, 'help_language_switch', 'Sistem', 'cara ganti bahasa,bahasa indonesia inggris,ubah bahasa ot', 'how to change language,switch english indonesian,bilingual mode', 'Buka Pengaturan di kanan atas lalu pilih bahasa Indonesia atau English.', 'Open Settings at the top right and select Indonesia or English.', 'HAPPY', 'EXPLAIN', 82, 1, 0, '2026-11-24 13:41:08'),
(98, 'help_voice_control', 'Sistem', 'suara tidak keluar,atur volume,ganti suara avatar,bisukan suara', 'no audio,change volume,change voice,mute avatar', 'Buka Pengaturan, pastikan Respon Suara aktif, dan atur Volume sesuai kebutuhan.', 'Open Settings, turn Voice Response on, and adjust the Volume slider.', 'SMILING', 'EXPLAIN', 83, 1, 0, '2026-11-24 13:41:08'),
(99, 'help_dashboard_access', 'Sistem', 'buka dashboard admin,login manajemen,kelola knowledge base', 'open admin dashboard,management login,manage knowledge', 'Klik ikon pengguna di pojok kanan atas untuk login ke Dashboard Manajemen.', 'Click the user icon at the top right to sign in to the Management Dashboard.', 'HAPPY', 'EXPLAIN', 82, 1, 0, '2026-11-24 13:41:08'),
(100, 'help_mic_usage', 'Sistem', 'cara pakai mikrofon,ngomong ke avatar,tombol mic,tidak ada mic', 'how to use microphone,talk to avatar,mic button', 'Klik tombol mikrofon di bagian bawah, ucapkan pertanyaan, lalu tunggu asisten menjawab.', 'Click the microphone button at the bottom, speak your question, and wait for the reply.', 'HAPPY', 'WAVE', 84, 1, 0, '2026-11-24 13:41:08'),
(101, 'exam_motivation', 'Motivasi', 'besok ujian,ujian uts,ujian uas,takut gagal ujian,persiapan sidang', 'exam tomorrow,midterm prep,final exam stress,thesis defense prep', 'Ulangi materi inti, latihan soal, berdoa, dan jaga istirahat sebelum ujian. Semoga lancar!', 'Review key topics, practice sample questions, pray, and rest well before your exam!', 'HAPPY', 'APPLAUSE', 80, 1, 0, '2026-11-24 13:41:08'),
(102, 'research_method', 'Akademik & AI', 'metodologi penelitian,rumusan masalah,kuantitatif kualitatif,tinjauan pustaka', 'research methodology,problem statement,literature review,methodology', 'Riset yang baik butuh rumusan masalah jelas, tinjauan pustaka, metode terukur, dan evaluasi objektif.', 'Good research needs a clear problem statement, literature review, sound method, and objective evaluation.', 'THINKING', 'EXPLAIN', 77, 1, 0, '2026-11-24 13:41:08'),
(103, 'apology_response', 'Etika', 'maaf ya,sorry,maaf bu,saya salah tanya', 'i am sorry,apologies,my mistake', 'Tidak masalah, santai saja. Ada yang ingin ditanyakan?', 'No worries at all. What would you like to ask?', 'SMILING', 'NOD', 82, 1, 0, '2026-11-24 13:41:08'),
(104, 'compliment_appearance', 'Sapaan', 'kamu cantik,bajunya bagus,kacamatanya keren,ruangan bagus', 'you look nice,cool glasses,great outfit,nice background', 'Terima kasih! Anda juga bisa mengganti jas, kacamata, dan latar 3D di Pengaturan.', 'Thanks! You can also customize outfits, glasses, and 3D rooms in Settings.', 'HAPPY', 'BOW', 80, 1, 0, '2026-11-24 13:41:08'),
(105, 'health_break_tip', 'Motivasi', 'mata lelah,lama depan laptop,sakit punggung ngoding,tips kesehatan mahasiswa', 'eye strain,long screen time,coding posture,student wellness', 'Terapkan aturan 20-20-20: tiap 20 menit melihat layar, tatap objek jauh 20 detik dan minum air.', 'Follow the 20-20-20 rule: every 20 minutes look away for 20 seconds and stay hydrated.', 'SMILING', 'NOD', 76, 1, 0, '2026-11-24 13:41:08'),
(106, 'time_management', 'Motivasi', 'manajemen waktu kuliah,atur jadwal belajar,sks banyak,prokrastinasi', 'time management,study schedule,beat procrastination', 'Atur prioritas harian, pecah tugas besar jadi sesi 30 menit, dan kerjakan yang utama dulu.', 'Prioritize key tasks, split big work into 30-minute blocks, and tackle hard items first.', 'SMILING', 'EXPLAIN', 77, 1, 0, '2026-11-24 13:41:08'),
(107, 'internship_prep', 'Akademik & AI', 'tips magang,persiapan kerja praktik,cv mahasiswa it,portofolio github', 'internship tips,student portfolio,resume advice,github profile', 'Siapkan 2–3 proyek nyata di GitHub dengan README rapi dan hasil yang terukur untuk portofolio.', 'Build 2–3 GitHub projects with clean READMEs and measurable results for your portfolio.', 'HAPPY', 'EXPLAIN', 78, 1, 0, '2026-11-24 13:41:08'),
(108, 'english_practice', 'Motivasi', 'cara lancar bahasa inggris,toefl it,latihan speaking,tips presentasi inggris', 'improve english,toefl preparation,speaking practice,english presentation', 'Ubah bahasa ke English di Pengaturan lalu latih percakapan suara secara rutin setiap hari.', 'Switch Language to English in Settings and practice live voice conversations daily.', 'HAPPY', 'WAVE', 78, 1, 0, '2026-11-24 13:41:08'),
(109, 'public_speaking', 'Motivasi', 'gugup presentasi,takut bicara depan kelas,tips presentasi skripsi', 'nervous presenting,public speaking tips,thesis presentation', 'Fokus pada 3 poin utama per slide, bicara dengan tempo tenang, dan kuasai isi karya Anda.', 'Focus on 3 key points per slide, speak at a steady pace, and stay confident in your work.', 'HAPPY', 'NOD', 77, 1, 0, '2026-11-24 13:41:08'),
(110, 'software_testing', 'Akademik & AI', 'unit testing,integration test,phpunit,pytest,kualitas software', 'unit testing,automated tests,phpunit,software qa', 'Unit, integration, dan E2E test memastikan perubahan kode baru tidak merusak fitur yang ada.', 'Unit, integration, and E2E tests verify new changes do not break existing features.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(111, 'api_rate_limit', 'Keamanan Siber', 'rate limiting,apa itu ddos,throttling api,proteksi spam chat', 'rate limiting,api throttling,spam protection,dos prevention', 'Rate limiting membatasi jumlah permintaan per IP per menit agar server tetap stabil.', 'Rate limiting caps requests per IP per minute to protect server stability.', 'SMILING', 'NOD', 76, 1, 0, '2026-11-24 13:41:08'),
(112, 'data_privacy_ethics', 'Keamanan Siber', 'privasi data,etika ai,penggunaan data chat,informasi sensitif', 'data privacy,ai ethics,chat logging transparency', 'Jangan masukkan password, nomor KTP, atau kredensial rahasia ke dalam prompt AI.', 'Never enter passwords, national IDs, or private credentials into AI prompts.', 'SMILING', 'NOD', 79, 1, 0, '2026-11-24 13:41:08'),
(113, 'agent_tools_overview', 'Sistem', 'function calling,sql assistant,kalkulator ai,cek waktu server,tools ot', 'function calling,ai tools,sql assistant,database stats tool', 'ot punya 100 Agent Tools untuk kalkulator, konverter, kalender, workflow kampus, SQL, dan API.', 'ot has 100 Agent Tools for math, converters, calendar, campus workflows, SQL, and APIs.', 'HAPPY', 'EXPLAIN', 84, 1, 0, '2026-11-24 13:41:08'),
(114, 'math_logic_help', 'Akademik & AI', 'bisa hitung matematika,hitung ipk,aljabar diskrit,logika informatika', 'can you calculate math,discrete math,boolean logic', 'Bisa! Coba ketik misalnya \'hitung 24 * 4 / 3\' untuk menghitung langsung di server.', 'Sure! Try asking \'calculate (24 * 4) / 3\' for an instant server calculation.', 'HAPPY', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(115, 'smart_greeting_info', 'Sistem', 'sapaan otomatis,auto greeting,sapaan sesuai waktu', 'auto greeting,time based greeting,smart greeting', 'Saat dibuka, avatar menyapa otomatis sesuai waktu lokal Anda (pagi, siang, atau malam).', 'On startup, the avatar greets you automatically based on your local time of day.', 'HAPPY', 'WAVE', 76, 1, 0, '2026-11-24 13:41:08'),
(116, 'emotion_detection_info', 'Sistem', 'deteksi emosi,ekspresi avatar,bisa marah sedih senang', 'emotion detection,facial expression,avatar mood', 'Sistem mendeteksi nada emosi pesan pengguna dan menyesuaikan ekspresi serta gestur avatar 3D.', 'The system detects user message emotion and updates the 3D avatar expression and gesture.', 'SMILING', 'EXPLAIN', 79, 1, 0, '2026-11-24 13:41:08'),
(117, 'long_term_memory_info', 'Sistem', 'memori jangka panjang,long term memory,ingat percakapan sebelumnya', 'long term memory,remember preferences,session memory', 'Memori jangka panjang menyimpan nama, prodi, semester, dan konteks penting sesi Anda.', 'Long-Term Memory saves your name, major, semester, and key session context.', 'SMILING', 'NOD', 79, 1, 0, '2026-11-24 13:41:08'),
(118, 'profanity_policy', 'Etika', 'kata kasar,filter kata kasar,moderasi chat,etika berbicara', 'profanity filter,bad words detection,chat moderation', 'Mohon gunakan bahasa yang sopan saat berinteraksi di sistem ini.', 'Please use polite language when interacting with this system.', 'SMILING', 'NOD', 78, 1, 0, '2026-11-24 13:41:08'),
(119, 'algo_programming', 'Kurikulum FILKOM', 'algoritma pemrograman,dasar coding,flowchart,pseudocode', 'algorithms and programming,basic coding,flowchart', 'Algoritma & Pemrograman membahas flowchart, percabangan, perulangan, fungsi, dan array.', 'Algorithms & Programming covers flowcharts, conditionals, loops, functions, and arrays.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(120, 'data_structures', 'Kurikulum FILKOM', 'struktur data,linked list,stack queue,binary tree,graf', 'data structures,linked list,tree graph,hash map', 'Struktur Data membahas Big-O pada Array, Linked List, Stack, Queue, Hash Table, Tree, dan Graph.', 'Data Structures covers Big-O using Arrays, Linked Lists, Stacks, Queues, Hash Tables, Trees, and Graphs.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(121, 'oop_paradigm', 'Kurikulum FILKOM', 'pbo,oop,pemrograman berorientasi objek,class inheritance polymorphism', 'object oriented programming,inheritance,polymorphism,encapsulation', 'OOP menerapkan Encapsulation, Inheritance, Polymorphism, dan Abstraction agar kode modular.', 'OOP applies Encapsulation, Inheritance, Polymorphism, and Abstraction for modular code.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(122, 'web_dev_stack', 'Kurikulum FILKOM', 'pemrograman web,html css js,php mysql,frontend backend', 'web programming,frontend backend,html css javascript', 'Pemrograman Web mencakup HTML/CSS/JS di frontend serta REST API dan database di backend.', 'Web Development spans HTML/CSS/JS frontends alongside REST APIs and backend databases.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(123, 'mobile_flutter', 'Kurikulum FILKOM', 'pemrograman mobile,android studio,flutter dart,aplikasi hp', 'mobile app development,flutter,android ios', 'Pengembangan Mobile di FILKOM memakai Flutter dan Kotlin untuk aplikasi Android/iOS terhubung API.', 'Mobile Development uses Flutter and Kotlin to build API-connected Android and iOS apps.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08');
