(125, 'computer_networks', 'Kurikulum FILKOM', 'jaringan komputer,tcp ip,osi layer,routing switching,subnetting', 'computer networks,tcp ip,osi model,subnetting', 'Jaringan Komputer membahas model OSI/TCP-IP, subnetting, HTTP/DNS/TLS, routing, dan VLAN.', 'Computer Networks covers OSI/TCP-IP, subnetting, HTTP/DNS/TLS, routing, and VLANs.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(126, 'software_engineering', 'Kurikulum FILKOM', 'rekayasa perangkat lunak,sdlc,scrum agile,diagram uml', 'software engineering,sdlc,agile scrum,uml diagrams', 'Rekayasa Perangkat Lunak mempraktikkan Agile/Scrum, UML, pola desain, dan pengujian mutu.', 'Software Engineering practices Agile/Scrum, UML modeling, design patterns, and QA.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(127, 'hci_uiux', 'Kurikulum FILKOM', 'interaksi manusia komputer,ui ux,figma prototype,usability testing', 'human computer interaction,ui ux design,usability heuristics', 'HCI/UI-UX berfokus pada riset pengguna, prototipe Figma, aksesibilitas, dan usability testing.', 'HCI/UI-UX focuses on user research, Figma prototyping, accessibility, and usability testing.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
