(129, 'linear_algebra_ai', 'Kurikulum FILKOM', 'aljabar linear,vektor matriks,eigenvalue,perkalian dot product', 'linear algebra,vectors matrices,eigenvalues,dot product', 'Aljabar Linear penting untuk AI karena mendasari vektor embedding, matriks, PCA, dan tensor.', 'Linear Algebra underpins AI through vector embeddings, matrices, PCA, and tensor math.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(130, 'probability_stats', 'Kurikulum FILKOM', 'statistika probabilitas,teorema bayes,distribusi normal,uji hipotesis', 'probability statistics,bayes theorem,hypothesis testing', 'Statistika & Probabilitas mencakup Teorema Bayes, regresi, distribusi, dan uji hipotesis.', 'Probability & Statistics covers Bayes\' theorem, regression, distributions, and hypothesis tests.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(131, 'cloud_devops', 'Kurikulum FILKOM', 'devops,ci cd pipeline,github actions,deployment server', 'devops,ci cd,continuous integration,deployment automation', 'DevOps mengotomasi build, pengujian, keamanan, dan deployment lewat pipeline CI/CD.', 'DevOps automates build, testing, security checks, and deployment via CI/CD pipelines.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
