(139, 'taxation_indo', 'Kurikulum FEB', 'perpajakan,pph 21,ppn,spt tahunan,brevet pajak', 'indonesian taxation,income tax,vat reporting', 'Perpajakan membahas PPh 21/23/Badan, PPN, serta pelaporan e-Faktur dan e-Bupot.', 'Taxation covers income tax, VAT, e-Faktur filing, and current Indonesian tax rules.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(140, 'entrepreneurship_hub', 'Kurikulum FEB', 'kewirausahaan,business model canvas,bmc,pitch deck startup', 'entrepreneurship,business model canvas,startup pitch deck', 'Kewirausahaan melatih penyusunan Business Model Canvas, validasi MVP, dan proyeksi arus kas.', 'Entrepreneurship teaches Business Model Canvas, MVP validation, and cash flow forecasting.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(141, 'nursing_anatomy', 'Kurikulum FIK', 'anatomi fisiologi,sistem kardiovaskular,pernapasan,saraf manusia', 'anatomy physiology,cardiovascular system,respiratory care', 'Anatomi & Fisiologi mempelajari struktur organ dan homeostasis tubuh sebagai dasar keperawatan.', 'Anatomy & Physiology studies organ structures and homeostasis as the basis of nursing care.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(142, 'nursing_osce', 'Kurikulum FIK', 'ujian osce,lab keperawatan,asuhan keperawatan,tanda tanda vital', 'osce exam,nursing skills lab,vital signs assessment', 'Ujian OSCE menilai keterampilan klinis seperti tanda vital, sterilisasi, dan komunikasi pasien.', 'Nursing OSCE tests clinical skills including vital signs, asepsis, and patient communication.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(143, 'nursing_ukom', 'Kurikulum FIK', 'ukom ners,uji kompetensi perawat,lulus profesi ners', 'ukom nursing,national nursing board exam,ners exit exam', 'Persiapan UKOM Ners melatih analisis kasus klinik keperawatan dari dewasa hingga gawat darurat.', 'UKOM Ners prep sharpens clinical reasoning across medical, maternity, pediatric, and ER care.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(144, 'nursing_community', 'Kurikulum FIK', 'keperawatan komunitas,promosi kesehatan,posyandu,kesehatan masyarakat', 'community health nursing,health promotion,public health', 'Keperawatan Komunitas melayani desa binaan lewat edukasi kesehatan, sanitasi, dan pencegahan.', 'Community Nursing partners with villages for health education, sanitation, and prevention.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(145, 'english_tesol', 'Kurikulum FKIP', 'tesol,tefl,pengajaran bahasa inggris,lesson plan bahasa inggris', 'tesol,tefl methodology,english lesson planning', 'Pendidikan Bahasa Inggris membina pedagogi komunikatif, Lesson Plan, linguistik, dan asesmen.', 'English Education covers communicative pedagogy, lesson planning, linguistics, and assessment.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(146, 'microteaching_lab', 'Kurikulum FKIP', 'microteaching,praktik mengajar,rpp kurikulum merdeka', 'microteaching lab,practice teaching,curriculum design', 'Lab Microteaching melatih praktik mengajar 10–15 menit dengan evaluasi penyampaian dan media.', 'Microteaching Lab trains 15-minute practice teaching sessions with structured feedback.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(147, 'educational_psychology', 'Kurikulum FKIP', 'psikologi pendidikan,teori belajar kognitif,motivasi siswa', 'educational psychology,cognitive learning theory,student motivation', 'Psikologi Pendidikan mengkaji perkembangan kognitif siswa, diferensiasi belajar, dan motivasi.', 'Educational Psychology studies cognitive development, differentiated learning, and motivation.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(148, 'agrotech_crops', 'Kurikulum FAPERTA', 'agroteknologi,budidaya tanaman,ilmu tanah,pemupukan organik', 'agrotechnology,crop science,soil fertility,organic farming', 'Agroteknologi memadukan ilmu tanah, pemuliaan tanaman, pengendalian hama, dan hidroponik.', 'Agrotechnology blends soil science, plant breeding, pest management, and hydroponics.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(149, 'theology_ethics', 'Kurikulum Filsafat', 'etika kristiani,hermeneutika,pelayanan pastoral,kepemimpinan rohani', 'christian ethics,hermeneutics,pastoral care,spiritual leadership', 'Fakultas Filsafat membekali kajian biblika, sejarah gereja, etika, dan pelayanan pastoral.', 'The Faculty of Philosophy covers biblical studies, church history, ethics, and pastoral care.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(150, 'grad_research_mm', 'Pascasarjana', 'tesis magister manajemen,riset bisnis s2,manajemen perubahan', 'master thesis mm,business research,change management', 'Magister Manajemen berfokus pada riset manajemen strategis, perubahan organisasi, dan tesis.', 'Master of Management focuses on strategic research, organizational change, and applied theses.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(151, 'dorm_crystal_edelweiss', 'Asrama ', 'asrama putra,asrama crystal,asrama edelweiss,asrama annex', 'mens dormitories,crystal hall,edelweiss hall', 'Asrama putra Crystal & Edelweiss memiliki jam belajar tenang pukul 19.30–21.30 WITA.', 'Men\'s Crystal & Edelweiss Halls observe evening study hours from 7:30 to 9:30 PM.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(152, 'dorm_jasmine', 'Asrama ', 'asrama putri,asrama jasmine,peraturan keluar asrama putri', 'womens dormitory,jasmine hall,dorm check in policy', 'Asrama putri Jasmine menerapkan sistem presensi keamanan dan jadwal izin keluar kampus.', 'Women\'s Jasmine Hall enforces resident check-in monitoring and scheduled off-campus permits.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(153, 'dean_list_honor', 'Akademik & AI', 'dean list,cum laude,predikat kelulusan,ipk terbaik', 'deans list,cum laude,academic honors,graduation distinction', 'IPS >= 3.50 (minimal 15 SKS) masuk Dean\'s List, dan IPK akhir >= 3.51 berpeluang Cum Laude.', 'Semester GPA >= 3.50 (min 15 credits) earns Dean\'s List; final GPA >= 3.51 qualifies for Cum Laude.', 'SMILING', 'EXPLAIN', 76, 1, 0, '2026-11-24 13:41:08'),
(154, 'assistant_location', 'Identitas', 'di mana kamu tinggal,dimana kamu tinggal,kamu tinggal di mana,kamu tinggal dimana,tempat tinggal kamu,di mana kamu berada,dimana kamu berada,lokasi kamu dimana,di mana lokasi kamu,kamu berasal dari mana,asal kamu dari mana', 'where do you live,where are you located,where are you based,where is ot,where are you from', 'Saya asisten virtual 3D yang beroperasi secara digital di Kampus , Airmadidi, Sulawesi Utara.', 'I\'m a 3D virtual assistant operating digitally at  Campus in Airmadidi, North Sulawesi.', 'HAPPY', 'EXPLAIN', 96, 1, 6, '2026-11-24 13:41:08'),
(155, 'daily_sleep_ideal', 'Kehidupan Sehari-hari', 'durasi tidur ideal,berapa jam tidur,susah tidur,cara tidur nyenyak,tips tidur nyenyak,mengatasi insomnia,jam tidur yang baik', 'ideal sleep duration,how much sleep,trouble sleeping,sleep better tips,insomnia tips,healthy sleep hours', 'Orang dewasa butuh 7–9 jam tidur per malam; hindari layar gadget 30 menit sebelum tidur.', 'Adults need 7–9 hours of sleep nightly; avoid screens 30 minutes before bed for better rest.', 'THINKING', 'EXPLAIN', 78, 1, 8, '2026-11-24 13:41:08'),
(156, 'daily_hydration_water', 'Kehidupan Sehari-hari', 'manfaat air putih,berapa liter air sehari,tanda dehidrasi,kebutuhan air harian,kebiasaan minum air,air putih sehari', 'benefits of drinking water,daily water intake,signs of dehydration,stay hydrated tips,how much water daily', 'Minum sekitar 2 liter (8 gelas) air putih per hari menjaga fokus, metabolisme, dan suhu tubuh.', 'Drinking around 2 liters (8 glasses) of water daily supports focus, metabolism, and hydration.', 'HAPPY', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(157, 'daily_caffeine_coffee', 'Kehidupan Sehari-hari', 'batas aman kopi,efek minum kopi,kapan waktu minum kopi,dampak kafein berlebih,batas aman kafein', 'safe coffee limit,caffeine side effects,best time for coffee,too much caffeine,safe caffeine intake', 'Batas aman kafein orang dewasa sekitar 2–3 cangkir kopi per hari; hindari minum terlalu malam.', 'Safe caffeine for most adults is about 2–3 cups of coffee daily; avoid drinking it late at night.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(158, 'daily_healthy_breakfast', 'Kehidupan Sehari-hari', 'pentingnya sarapan,menu sarapan sehat,manfaat sarapan pagi,sarapan praktis bergizi,sarapan sehat', 'importance of breakfast,healthy breakfast ideas,benefits of breakfast,quick nutritious breakfast', 'Sarapan sehat memadukan protein, serat, dan karbohidrat kompleks seperti telur, oat, dan buah.', 'A balanced breakfast combines protein, fiber, and complex carbs like eggs, oats, and fruit.', 'SMILING', 'NOD', 76, 1, 1, '2026-11-24 13:41:08'),
(159, 'daily_flu_prevention', 'Kehidupan Sehari-hari', 'cara mencegah flu,obat alami batuk pilek,daya tahan tubuh menurun,cara mengatasi flu,cegah sakit flu', 'prevent common cold,flu recovery tips,boost immune system,sore throat relief,common cold care', 'Istirahat cukup, minum air hangat, makan bergizi, dan rajin cuci tangan bantu mempercepat pulih.', 'Get enough rest, drink warm fluids, eat nutritious food, and wash hands often to recover faster.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(160, 'daily_food_expiry_label', 'Kehidupan Sehari-hari', 'beda expired date dan best before,arti best before,makanan lewat best before,cek tanggal kedaluwarsa,kedaluwarsa makanan', 'expired date vs best before,use by vs best before,food expiration label,is expired food safe', 'Use By/Exp adalah batas keamanan pangan, sedangkan Best Before menandakan batas mutu rasa terbaik.', 'Use By/Exp is the food-safety cutoff, while Best Before indicates when peak flavor and quality fade.', 'THINKING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(161, 'daily_exercise_routine', 'Kehidupan Sehari-hari', 'olahraga ringan harian,durasi olahraga seminggu,manfaat jalan kaki,olahraga pemula,tips mulai olahraga', 'daily light exercise,weekly workout duration,benefits of walking,beginner workout routine,start exercising', 'Jalan cepat atau olahraga ringan 30 menit sehari baik untuk jantung, otot, dan suasana hati.', '30 minutes of brisk walking or light exercise daily improves heart health, strength, and mood.', 'HAPPY', 'APPLAUSE', 76, 1, 1, '2026-11-24 13:41:08'),
(162, 'daily_ergonomic_posture', 'Kehidupan Sehari-hari', 'postur duduk benar,sakit punggung kerja,posisi meja kerja,posisi duduk depan komputer,ergonomi meja kerja', 'correct sitting posture,back pain desk job,ergonomic desk setup,computer posture tips', 'Duduk tegak dengan layar sejajar mata, kaki menapak lantai, dan lakukan peregangan tiap 1 jam.', 'Sit upright with your screen at eye level, feet flat on the floor, and stretch once every hour.', 'SMILING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(163, 'daily_stress_breathing', 'Kehidupan Sehari-hari', 'cara atasi stres harian,mengatasi stres kerja,teknik pernapasan relaksasi,menenangkan pikiran,cara mengatasi burnout', 'daily stress relief,breathing technique calm,relax mind quickly,overcoming burnout,4 7 8 breathing', 'Coba teknik napas 4-7-8: tarik 4 detik, tahan 7 detik, hembuskan 8 detik untuk menenangkan diri.', 'Try 4-7-8 breathing: inhale 4 seconds, hold 7 seconds, and exhale 8 seconds to calm down fast.', 'SMILING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08');
INSERT INTO `tbl_static_knowledge` (`id`, `topic_code`, `category`, `keywords_id`, `keywords_en`, `response_id`, `response_en`, `expression`, `gesture`, `priority`, `is_active`, `hit_count`, `created_at`) VALUES
(164, 'daily_first_aid_basics', 'Kehidupan Sehari-hari', 'pertolongan pertama luka bakar,penanganan luka gores,isi kotak p3k,pertolongan mimisan,kena minyak panas', 'burn first aid,minor cut treatment,first aid kit items,nosebleed first aid', 'Untuk luka bakar ringan, alirkan air dingin 10–15 menit; jangan oleskan pasta gigi atau mentega.', 'For minor burns, run cool water for 10–15 minutes; never apply toothpaste, oil, or butter.', 'THINKING', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(165, 'daily_phone_battery', 'Kehidupan Sehari-hari', 'cara merawat baterai hp,baterai cepat habis,baterai hp boros,kebiasaan charge hp,jaga battery health', 'phone battery care,battery draining fast,phone charging habits,preserve battery health', 'Jaga daya baterai ideal di rentang 20%–80%, hindari panas berlebih, dan pakai charger resmi.', 'Keep battery levels mostly between 20%–80%, avoid overheating, and use certified chargers.', 'THINKING', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(166, 'daily_wifi_slow_fix', 'Kehidupan Sehari-hari', 'wifi lambat cara atasi,internet lemot di rumah,posisi router wifi,wifi lemot solusi,perkuat sinyal wifi', 'slow wifi fix,internet slow at home,wifi router placement,improve wifi signal', 'Letakkan router di area terbuka dan tinggi, restart berkala, lalu pakai pita 5 GHz bila dekat.', 'Place your router in a central open spot, reboot it occasionally, and use 5 GHz when nearby.', 'THINKING', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(167, 'daily_password_hygiene', 'Kehidupan Sehari-hari', 'cara buat password aman,keamanan akun media sosial,manfaat 2fa,autentikasi dua faktor,tips password kuat', 'strong password tips,social media security,two factor authentication,secure online accounts', 'Pakai sandi unik minimal 12 karakter berbeda tiap akun dan aktifkan verifikasi dua langkah.', 'Use unique passwords of at least 12 characters per account and turn on two-factor authentication.', 'THINKING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(168, 'daily_phishing_scam', 'Kehidupan Sehari-hari', 'ciri penipuan online,modus link phising,penipuan undangan apk,aman transaksi online,hindari penipuan wa', 'spot online scams,phishing link signs,apk scam warning,safe online shopping,avoid online fraud', 'Jangan klik tautan atau file APK asing, dan jangan pernah bagikan kode OTP ke siapa pun.', 'Never click unknown links or APK files, and never share OTP verification codes with anyone.', 'CONFUSED', 'EXPLAIN', 79, 1, 1, '2026-11-24 13:41:08'),
(169, 'daily_backup_data', 'Kehidupan Sehari-hari', 'cara backup data penting,aturan backup 3 2 1,amankan foto dan file,penyimpanan cloud aman', 'how to backup files,3 2 1 backup rule,cloud storage backup,protect important data', 'Terapkan aturan backup 3-2-1: 3 salinan data di 2 media berbeda, dengan 1 tersimpan di cloud.', 'Follow the 3-2-1 rule: keep 3 copies of data on 2 media types, with 1 copy backed up to the cloud.', 'SMILING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(170, 'daily_laptop_care', 'Kehidupan Sehari-hari', 'cara merawat laptop,laptop cepat panas,bersihkan kipas laptop,laptop lemot solusi,mengatasi laptop overheat', 'laptop maintenance tips,laptop overheating fix,speed up slow laptop,clean laptop vents', 'Pakai laptop di permukaan keras agar ventilasi lancar, tutup app berat, dan update OS secara rutin.', 'Use laptops on hard flat surfaces for airflow, close heavy background apps, and keep OS updated.', 'THINKING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(171, 'daily_phone_wet', 'Kehidupan Sehari-hari', 'hp kena air solusi,hp masuk air harus apa,keringkan hp basah,speaker hp kemasukan air', 'wet phone fix,phone dropped in water,dry wet smartphone,water in phone speaker', 'Segera matikan HP yang basah, lap kering, dan diamkan hingga kering total sebelum dinyalakan.', 'Power off a wet phone immediately, wipe it dry, and let it air-dry completely before charging.', 'SURPRISED', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(172, 'daily_free_storage', 'Kehidupan Sehari-hari', 'memori hp penuh,cara legakan penyimpanan,hapus cache aman,hemat ruang penyimpanan,storage penuh', 'phone storage full,free up disk space,clear app cache safely,low storage fix', 'Hapus cache aplikasi, pindahkan foto/video besar ke cloud, lalu buang file unduhan duplikat.', 'Clear app caches, move large photos or videos to cloud/external drives, and remove duplicate files.', 'SMILING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(173, 'daily_pdf_word_tools', 'Kehidupan Sehari-hari', 'kompres ukuran pdf,gabung file pdf,ubah word ke pdf,convert word ke pdf,tips dokumen pdf', 'compress pdf size,merge pdf files,convert word to pdf,digital document tips', 'Simpan file Word langsung lewat Export atau Save As PDF agar tata letak dokumen tetap rapi.', 'Use Export or Save As PDF directly inside Word or Docs so your layout stays consistent everywhere.', 'SMILING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(174, 'daily_ai_smart_use', 'Kehidupan Sehari-hari', 'cara efektif pakai ai,verifikasi jawaban ai,etika gunakan ai,waspada halusinasi ai,tips pakai chatgpt,selalu,jawab,lalu', 'use ai effectively,verify ai answers,ai hallucinations check,smart ai prompting', 'Tulis prompt spesifik dengan konteks jelas, lalu selalu cek ulang fakta penting dari jawaban AI.', 'Write clear, specific prompts with context, and always fact-check critical details from AI replies.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(175, 'daily_budgeting_rule', 'Kehidupan Sehari-hari', 'cara mengatur keuangan,rumus 50 30 20,tips menabung gaji,kelola uang bulanan,cara menabung efektif,mengatur,keuangan,bulanan,atur,uang,bulan', 'personal budgeting tips,50 30 20 budget rule,how to save money,manage monthly expenses', 'Pakai aturan 50/30/20: 50% untuk kebutuhan pokok, 30% keinginan, dan minimal 20% tabungan.', 'Try the 50/30/20 budget rule: 50% for needs, 30% for wants, and at least 20% for savings.', 'SMILING', 'EXPLAIN', 79, 1, 10, '2026-11-24 13:41:08'),
(176, 'daily_emergency_fund', 'Kehidupan Sehari-hari', 'berapa dana darurat ideal,pentingnya dana darurat,cara kumpul dana darurat,simpanan dana darurat', 'ideal emergency fund,why emergency fund matters,how much emergency savings', 'Siapkan dana darurat minimal 3–6 kali pengeluaran bulanan di rekening terpisah yang likuid.', 'Aim for 3–6 months of living expenses in an accessible separate account as your emergency fund.', 'THINKING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(177, 'daily_smart_shopping', 'Kehidupan Sehari-hari', 'cara hindari belanja impulsif,aturan belanja 24 jam,tips belanja hemat,hindari boros belanja', 'avoid impulse buying,24 hour shopping rule,smart grocery shopping,save money shopping', 'Buat daftar belanja sebelum membeli dan tunda 24 jam sebelum checkout barang non-pokok.', 'Shop with a written list and wait 24 hours before non-essential purchases to avoid impulse buys.', 'THINKING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(178, 'daily_electricity_saving', 'Kehidupan Sehari-hari', 'cara hemat listrik,menghemat listrik rumah,tagihan listrik bengkak,suhu ac hemat energi,cabut colokan listrik,hemat', 'save electricity at home,reduce electric bill,ac energy saving temperature,unplug idle devices', 'Atur AC di suhu 24–25°C, matikan lampu ruangan kosong, dan cabut pengisi daya bila tidak dipakai.', 'Set AC around 24–25°C, turn off unused lights, and unplug idle chargers to cut power bills.', 'SMILING', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(179, 'daily_cv_resume_tips', 'Kehidupan Sehari-hari', 'cara membuat cv menarik,tips menulis resume,cv ats friendly,persiapan melamar kerja,cara bikin cv', 'write good resume,ats friendly cv tips,job application resume,cv formatting tips', 'Buat CV ringkas 1–2 halaman, pakai poin pencapaian terukur, dan sesuaikan kata kunci posisi kerja.', 'Keep your resume concise at 1–2 pages, highlight measurable achievements, and tailor keywords.', 'SMILING', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(180, 'daily_job_interview', 'Kehidupan Sehari-hari', 'tips wawancara kerja,persiapan interview kerja,jawab kelebihan kekurangan,metode star interview', 'job interview tips,interview preparation,star method interview,common interview answer', 'Pelajari profil perusahaan, jawab pertanyaan pengalaman dengan metode STAR, dan hadir tepat waktu.', 'Research the company beforehand, answer behavioral questions using STAR, and arrive on time.', 'HAPPY', 'EXPLAIN', 78, 1, 1, '2026-11-24 13:41:08'),
(181, 'daily_procrastination_fix', 'Kehidupan Sehari-hari', 'cara mengatasi menunda pekerjaan,aturan 2 menit produktif,mulai tugas malas,berhenti menunda tugas,kebiasaan menunda', 'stop procrastinating,two minute productivity rule,avoid delaying tasks,start difficult tasks', 'Mulai dari langkah kecil 2 menit pertama atau pecah tugas besar jadi target mini agar cepat jalan.', 'Start with a tiny 2-minute step or break big tasks into small milestones to build momentum.', 'SMILING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(182, 'daily_focus_deepwork', 'Kehidupan Sehari-hari', 'cara fokus kerja tanpa gangguan,kurangi distraksi hp,deep work produktif,tips agar fokus belajar,susah fokus', 'stay focused at work,reduce phone distractions,deep work habits,manage notifications,improve concentration', 'Aktifkan mode Jangan Ganggu saat bekerja dan jadwalkan waktu khusus untuk mengecek pesan masuk.', 'Turn on Do Not Disturb during focus blocks and batch-check messages or social apps on schedule.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(183, 'daily_note_taking', 'Kehidupan Sehari-hari', 'cara mencatat efektif,metode cornell notes,rangkum catatan cepat,tips catat rapat', 'effective note taking,cornell notes method,summarize meeting notes,effective study notes', 'Catat poin inti dengan kata sendiri, pisahkan kata kunci di pinggir, lalu buat ringkasan singkat.', 'Capture key ideas in your own words, list cues in the margin, and write a 2–3 line summary.', 'SMILING', 'EXPLAIN', 74, 1, 1, '2026-11-24 13:41:08'),
(184, 'daily_food_storage', 'Kehidupan Sehari-hari', 'cara simpan makanan di kulkas,masa simpan makanan,makanan awet segar,simpan sayuran kulkas', 'store food in fridge,food shelf life,keep vegetables fresh,refrigerator storage tips', 'Simpan sisa makanan di wadah kedap udara paling lama 3–4 hari di kulkas pada suhu di bawah 4°C.', 'Store leftovers in airtight containers for 3–4 days max inside a refrigerator kept below 4°C.', 'SMILING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(185, 'daily_stain_removal', 'Kehidupan Sehari-hari', 'hilangkan noda baju,noda kopi di pakaian,cara cuci noda membandel,noda tinta baju', 'remove clothes stain,coffee stain on shirt,stubborn stain removal,ink stain laundry', 'Bilas noda segera dengan air dingin dari sisi dalam kain, lalu oles sabun cair sebelum dicuci.', 'Flush fresh stains from the back with cold water right away, then pretreat gently with liquid soap.', 'SMILING', 'EXPLAIN', 74, 1, 1, '2026-11-24 13:41:08'),
(186, 'daily_kitchen_odor', 'Kehidupan Sehari-hari', 'hilangkan bau kulkas,hilangkan bau ruangan,penyerap bau alami,soda kue penghilang bau', 'remove fridge odor,baking soda odor absorber,natural room deodorizer,clean smelly fridge', 'Taruh mangkuk terbuka berisi soda kue atau bubuk kopi kering di sudut kulkas untuk menyerap bau.', 'Place an open bowl of baking soda or dry coffee grounds in the fridge to absorb unwanted odors.', 'SMILING', 'NOD', 74, 1, 1, '2026-11-24 13:41:08'),
(187, 'daily_travel_packing', 'Kehidupan Sehari-hari', 'tips packing koper rapi,daftar barang bawaan travel,persiapan bepergian jauh,packing hemat tempat', 'smart packing tips,travel packing checklist,roll clothes packing,prepare for trip', 'Gulung pakaian untuk hemat ruang, pisahkan kabel dan obat dalam pouch, serta bawa salinan dokumen.', 'Roll clothes to save space, keep chargers and meds in pouches, and carry digital copies of IDs.', 'HAPPY', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(188, 'daily_vehicle_check', 'Kehidupan Sehari-hari', 'perawatan motor rutin,cek kendaraan sebelum jalan,kapan ganti oli motor,tekanan angin ban', 'motorcycle maintenance,pre trip car check,oil change interval,tire pressure check', 'Cek tekanan ban, rem, lampu, dan oli sebelum perjalanan jauh; ganti oli motor tiap 2.000–3.000 km.', 'Check tire pressure, brakes, lights, and engine oil before trips; routine service prevents breakdowns.', 'THINKING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(189, 'daily_rainy_weather_prep', 'Kehidupan Sehari-hari', 'persiapan musim hujan,tips berkendara saat hujan,tips aman hujan deras,antisipasi banjir', 'rainy season prep,safe driving in rain,rainy day essentials,flood safety tips', 'Siapkan jas hujan atau payung, jaga jarak pengereman saat berkendara, dan hindari genangan dalam.', 'Carry a raincoat or umbrella, keep extra braking distance in rain, and avoid deep floodwater.', 'SMILING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(190, 'daily_home_safety', 'Kehidupan Sehari-hari', 'keamanan rumah ditinggal,cek sebelum tidur malam,aman tabung gas,cegah korsleting listrik', 'home safety checklist,check before leaving home,prevent electrical fire,gas leak safety', 'Pastikan kompor dan regulator gas rapat, cabut alat pemanas, lalu kunci pintu sebelum pergi/tidur.', 'Verify stove and gas valves are off, unplug heating appliances, and lock doors before leaving.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(191, 'daily_trash_sorting', 'Kehidupan Sehari-hari', 'cara pilah sampah rumah,bedakan sampah organik anorganik,daur ulang sampah plastik,kompos rumah tangga', 'sort household waste,organic vs inorganic trash,recycle plastic at home,home composting basics', 'Pisahkan sampah organik sisa makanan, anorganik bersih yang bisa didaur ulang, dan limbah B3.', 'Separate food/organic waste, clean recyclables like plastic/paper, and hazardous items like batteries.', 'SMILING', 'NOD', 74, 1, 1, '2026-11-24 13:41:08'),
(192, 'daily_polite_email', 'Kehidupan Sehari-hari', 'cara tulis email profesional,etika kirim pesan wa dosen,struktur email resmi,salam pembuka email', 'write professional email,polite email etiquette,subject line email tips,formal message format', 'Tulis subjek jelas, sapaan sopan, maksud singkat di awal, lalu tutup dengan ucapan terima kasih.', 'Use a clear subject, polite greeting, concise request upfront, and end with a courteous thank-you.', 'SMILING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(193, 'daily_active_listening', 'Kehidupan Sehari-hari', 'cara komunikasi efektif,tips mendengarkan aktif,hindari salah paham,komunikasi asertif', 'effective communication,active listening skills,avoid misunderstandings,assertive communication', 'Dengarkan tanpa memotong, rangkum poin penting lawan bicara, dan sampaikan pendapat dengan sopan.', 'Listen without interrupting, paraphrase key points to confirm, and express views respectfully.', 'SMILING', 'NOD', 74, 1, 1, '2026-11-24 13:41:08'),
(194, 'daily_sky_blue_why', 'Kehidupan Sehari-hari', 'kenapa langit biru,langit berwarna biru,mengapa senja jingga,hamburan rayleigh,warna langit biru', 'why is the sky blue,why sunset is orange,rayleigh scattering simple,sky color explanation', 'Molekul udara menghamburkan cahaya biru matahari lebih kuat ke segala arah dibanding warna lain.', 'Air molecules scatter shorter blue wavelengths of sunlight in all directions more than red light.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(195, 'daily_rainbow_why', 'Kehidupan Sehari-hari', 'kenapa pelangi muncul,terjadinya pelangi,proses pelangi,mengapa ada pelangi', 'how rainbows form,why rainbows appear,colors of rainbow,rain and sunlight rainbow', 'Pelangi terbentuk saat cahaya matahari dibiaskan dan dipantulkan oleh tetesan air hujan di udara.', 'Rainbows form when sunlight refracts and reflects inside millions of airborne water droplets.', 'HAPPY', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(196, 'daily_timezones_indonesia', 'Kehidupan Sehari-hari', 'pembagian waktu indonesia,beda wib wita wit,selisih jam wita dan wib,zona waktu indonesia', 'indonesia time zones,difference wib wita wit,wita vs wib hours,indonesia utc offset', 'Indonesia terbagi 3 zona: WIB (UTC+7), WITA (UTC+8, +1 jam dari WIB), dan WIT (UTC+9, +2 jam).', 'Indonesia has 3 time zones: WIB (UTC+7), WITA (UTC+8, +1h from WIB), and WIT (UTC+9, +2h).', 'SMILING', 'EXPLAIN', 77, 1, 1, '2026-11-24 13:41:08'),
(197, 'daily_boiling_freezing', 'Kehidupan Sehari-hari', 'titik didih air,titik beku air,suhu air mendidih,suhu normal tubuh manusia,suhu tubuh normal', 'boiling point of water,freezing point water,normal human body temperature,celsius water freeze', 'Pada tekanan normal, air membeku di 0°C dan mendidih di 100°C; suhu tubuh normal 36,5–37,2°C.', 'At sea level, water freezes at 0°C and boils at 100°C; normal body temperature is 36.5–37.2°C.', 'THINKING', 'EXPLAIN', 76, 1, 1, '2026-11-24 13:41:08'),
(198, 'daily_leap_year', 'Kehidupan Sehari-hari', 'tahun kabisat,februari 29 hari,cara cek tahun kabisat,jumlah hari setahun kabisat', 'what is a leap year,why february has 29 days,how leap year works,days in a leap year', 'Tahun kabisat terjadi tiap 4 tahun (366 hari, Februari 29 hari) agar kalender selaras orbit Bumi.', 'A leap year adds Feb 29 every 4 years (366 days) so our calendar stays aligned with Earth\'s orbit.', 'THINKING', 'EXPLAIN', 75, 1, 1, '2026-11-24 13:41:08'),
(199, 'daily_emergency_numbers_id', 'Kehidupan Sehari-hari', 'nomor darurat indonesia,telepon polisi ambulans damkar,call center darurat 112,nomor darurat nasional', 'indonesia emergency numbers,police ambulance number indonesia,112 emergency hotline,fire brigade number', 'Nomor darurat terpadu Indonesia adalah 112; Polisi 110, Ambulans 118/119, dan Pemadam 113.', 'Indonesia\'s unified emergency hotline is 112; Police 110, Ambulance 118/119, and Fire Rescue 113.', 'SURPRISED', 'EXPLAIN', 80, 1, 8, '2026-11-24 13:41:08'),
(200, 'assistant_nature', 'Identitas', 'apakah kamu manusia,kamu manusia,kamu robot,kamu ai,apakah kamu ai,kamu manusia atau robot,kamu manusia atau ai,kamu makhluk hidup,apakah kamu mesin', 'are you human,are you a human,are you robot,are you a robot,are you ai,are you an ai,human or ai', 'Bukan, saya ot v.2.0.1, asisten virtual berbasis AI di Universitas—bukan manusia.', 'No, I am ot v.2.0.1, an AI virtual assistant at Universitas—not human.', 'SMILING', 'PRESENT', 98, 1, 5, '2026-11-24 13:41:08'),
(201, 'daily_healthy_lifestyle', 'Kehidupan Sehari-hari', 'cara agar hidup sehat,cara hidup sehat,agar hidup sehat,pola hidup sehat,tips hidup sehat,gaya hidup sehat,cara menjaga kesehatan,hidup sehat,hidup,sehat', 'how to live healthy,healthy lifestyle,tips to stay healthy,healthy habits', 'Makan bergizi seimbang, minum air 2 liter sehari, olahraga teratur, tidur 7–9 jam, dan kelola stres.', 'Eat balanced nutrition, drink 2L water daily, exercise regularly, sleep 7–9 hours, and manage stress.', 'HAPPY', 'PRESENT', 82, 1, 6, '2026-11-24 13:41:08');

DROP TABLE IF EXISTS `tbl_student_enrollments`;
CREATE TABLE `tbl_student_enrollments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `course_id` int(11) NOT NULL,
  `semester_label` varchar(32) NOT NULL DEFAULT '2026_2027_1',
  `grade_letter` varchar(4) DEFAULT 'A',
  `grade_points` decimal(3,2) DEFAULT 4.00,
  `status` enum('enrolled','completed','dropped') NOT NULL DEFAULT 'enrolled',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_enroll_stu_course_sem` (`student_id`,`course_id`,`semester_label`),
  KEY `idx_se_student_sem` (`student_id`,`semester_label`),
  KEY `idx_se_course` (`course_id`),
  CONSTRAINT `fk_se_course` FOREIGN KEY (`course_id`) REFERENCES `tbl_courses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_se_stu` FOREIGN KEY (`student_id`) REFERENCES `tbl_students` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

