DROP TABLE IF EXISTS `tbl_students`;
CREATE TABLE `tbl_students` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nim` varchar(32) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `study_program_id` int(11) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `cohort_year` int(11) NOT NULL DEFAULT 2023,
  `current_semester` int(11) NOT NULL DEFAULT 5,
  `gpa` decimal(3,2) NOT NULL DEFAULT 3.50,
  `total_credits` int(11) NOT NULL DEFAULT 96,
  `academic_status` enum('active','probation','leave','graduated','inactive') NOT NULL DEFAULT 'active',
  `advisor_lecturer_id` int(11) DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_students_nim` (`nim`),
  UNIQUE KEY `uk_students_user` (`user_id`),
  KEY `idx_students_prog_status` (`study_program_id`,`academic_status`,`deleted_at`),
  KEY `fk_stu_adv` (`advisor_lecturer_id`),
  CONSTRAINT `fk_stu_adv` FOREIGN KEY (`advisor_lecturer_id`) REFERENCES `tbl_lecturers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_stu_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_stu_user` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

