  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `study_program_id` int(11) NOT NULL,
  `supervisor_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `stage` enum('proposal','research','drafting','defense_ready','completed') NOT NULL DEFAULT 'proposal',
  `progress_pct` int(11) NOT NULL DEFAULT 25,
  `similarity_pct` decimal(4,1) NOT NULL DEFAULT 12.0,
  `status` enum('on_track','at_risk','delayed','completed') NOT NULL DEFAULT 'on_track',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_thesis_prog_status` (`study_program_id`,`status`),
  KEY `idx_thesis_student` (`student_id`),
  KEY `fk_th_sup` (`supervisor_id`),
  CONSTRAINT `fk_th_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_th_stu` FOREIGN KEY (`student_id`) REFERENCES `tbl_students` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_th_sup` FOREIGN KEY (`supervisor_id`) REFERENCES `tbl_lecturers` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

