  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_code` varchar(64) NOT NULL,
  `preferred_name` varchar(100) DEFAULT NULL,
  `preferred_language` varchar(8) DEFAULT 'id',
  `preferred_style` varchar(32) DEFAULT 'ramah_akademik',
  `voice_personality` varchar(32) DEFAULT 'warm_lecturer',
  `interests_topics` varchar(255) DEFAULT NULL,
  `project_context` text DEFAULT NULL,
  `last_emotion` varchar(32) DEFAULT 'HAPPY',
  `conversation_summary` text DEFAULT NULL,
