  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_up_session` (`session_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DROP TABLE IF EXISTS `tbl_user_role_history`;
CREATE TABLE `tbl_user_role_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `role_id` int(11) NOT NULL,
  `study_program_id` int(11) DEFAULT NULL,
  `replaced_user_id` int(11) DEFAULT NULL,
  `assigned_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `assignment_status` enum('active','ended') NOT NULL DEFAULT 'active',
  `replacement_reason` varchar(255) DEFAULT NULL,
  `assigned_by` varchar(64) NOT NULL DEFAULT 'system',
  `ended_by` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_urh_role_dates` (`role_id`,`assigned_at`,`ended_at`),
  KEY `idx_urh_user` (`user_id`,`assignment_status`),
  KEY `fk_urh_prog` (`study_program_id`),
  CONSTRAINT `fk_urh_prog` FOREIGN KEY (`study_program_id`) REFERENCES `tbl_study_programs` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_urh_role` FOREIGN KEY (`role_id`) REFERENCES `tbl_roles` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_urh_user` FOREIGN KEY (`user_id`) REFERENCES `tbl_users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

