DROP TABLE IF EXISTS `tbl_users`;
CREATE TABLE `tbl_users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(64) NOT NULL,
  `email` varchar(120) NOT NULL,
  `full_name` varchar(120) NOT NULL,
  `password_hash` varchar(255) NOT NULL,
  `department` varchar(120) DEFAULT 'Fakultas Ilmu Komputer',
  `phone` varchar(32) DEFAULT NULL,
  `avatar_color` varchar(24) DEFAULT '#2563eb',
  `status` enum('active','inactive','suspended') NOT NULL DEFAULT 'active',
  `mfa_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `mfa_secret_encrypted` text DEFAULT NULL,
  `reset_token_hash` varchar(128) DEFAULT NULL,
  `reset_token_expires_at` datetime DEFAULT NULL,
  `failed_attempts` int(11) NOT NULL DEFAULT 0,
  `locked_until` datetime DEFAULT NULL,
  `last_login_at` datetime DEFAULT NULL,
  `last_login_ip` varchar(45) DEFAULT NULL,
  `created_by` varchar(64) DEFAULT 'system',
  `deleted_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_users_username` (`username`),
  UNIQUE KEY `uk_users_email` (`email`),
  KEY `idx_users_status_deleted` (`status`,`deleted_at`),
  KEY `idx_users_reset_token` (`reset_token_hash`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

