DROP TABLE IF EXISTS `tbl_va_conversations`;
CREATE TABLE `tbl_va_conversations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `session_code` varchar(64) NOT NULL DEFAULT 'DEFAULT',
  `user_identifier` varchar(120) DEFAULT 'Guest',
  `language` enum('id','en') NOT NULL DEFAULT 'id',
  `detected_language` varchar(16) NOT NULL DEFAULT 'id',
  `user_message` text NOT NULL,
  `assistant_response` text NOT NULL,
  `expression` varchar(32) NOT NULL DEFAULT 'HAPPY',
  `gesture` varchar(32) NOT NULL DEFAULT 'NONE',
  `emotion_detected` varchar(32) NOT NULL DEFAULT 'neutral',
  `avatar_state` varchar(32) NOT NULL DEFAULT 'SPEAKING',
  `response_source` varchar(48) NOT NULL DEFAULT 'Static KB',
  `rag_reference` varchar(255) DEFAULT NULL,
  `tool_called` varchar(64) DEFAULT NULL,
  `ai_eval_score` decimal(4,2) NOT NULL DEFAULT 0.95,
  `follow_up_question` varchar(255) DEFAULT NULL,
  `user_satisfaction` tinyint(1) NOT NULL DEFAULT 0,
  `implicit_feedback` tinyint(1) NOT NULL DEFAULT 0,
  `is_unanswered` tinyint(1) NOT NULL DEFAULT 0,
  `failure_reason` varchar(120) DEFAULT NULL,
  `intent_tag` varchar(64) NOT NULL DEFAULT 'general',
  `flow_status` enum('resolved','continued','rephrased','stalled','abandoned') NOT NULL DEFAULT 'continued',
  `feedback_note` varchar(255) DEFAULT NULL,
  `learned_item_id` int(11) DEFAULT NULL,
  `is_profane` tinyint(1) NOT NULL DEFAULT 0,
  `profanity_words` varchar(255) DEFAULT NULL,
  `profanity_severity` enum('None','Low','Medium','High') NOT NULL DEFAULT 'None',
  `ip_address` varchar(45) NOT NULL DEFAULT '127.0.0.1',
  `location_label` varchar(120) NOT NULL DEFAULT 'Manado / Airmadidi, ID',
  `device_type` varchar(32) NOT NULL DEFAULT 'Desktop',
  `browser_os` varchar(120) NOT NULL DEFAULT 'Chrome / Windows',
  `user_agent` varchar(255) DEFAULT NULL,
  `latency_ms` int(11) NOT NULL DEFAULT 15,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_va_sess_lang` (`session_code`,`language`),
  KEY `idx_va_profane` (`is_profane`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
